"""Regroupement thématique des scripts de travail du projet.

IMPORTANT
---------
Les codes historiques n'ont pas été supprimés : leur contenu original est
conservé dans ``SCRIPTS``. Cette organisation évite d'avoir plus de cent
fichiers à la racine tout en maintenant la traçabilité et la reproductibilité.

Utilisation :
    python 11_analyse_modelisation_prevision.py --list
    python 11_analyse_modelisation_prevision.py NOM_DU_SCRIPT_SANS_EXTENSION

L'exécution se fait depuis la racine du projet afin de conserver les chemins
de fichiers attendus par les programmes historiques.
"""

from __future__ import annotations

import argparse
import os
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent

# Chaque valeur contient, sans modification, le code source de l'ancien script.
SCRIPTS = {
    '34_prepare_modeling_datasets.py': '"""\nPréparation des jeux de données pour l\'explication et la prévision de l\'IS.\n\nLe script crée des ratios, retards, taux de croissance et indicateurs de\nvaleurs manquantes. Il construit ensuite :\n- un jeu contemporain (variables t et IS t), utile pour l\'analyse explicative ;\n- un jeu prédictif réel (variables disponibles à t et IS cible à t+1).\n\nLe découpage est strictement temporel afin d\'évaluer les modèles sur des années\npostérieures à celles utilisées pour leur apprentissage.\n"""\n\nfrom pathlib import Path\nimport re\nimport unicodedata\n\nimport numpy as np\nimport pandas as pd\n\n\nOUTPUT_DIR = Path("data/output")\nPANEL_FILE = OUTPUT_DIR / "diagnostic_panel_is_financier.xlsx"\nOUTPUT_FILE = OUTPUT_DIR / "jeux_modelisation_is.xlsx"\nREFERENCE_CSV = OUTPUT_DIR / "modelisation_reference_t.csv"\nFORECAST_CSV = OUTPUT_DIR / "prevision_is_t_plus_1.csv"\n# Version figée de la base financière, enregistrée dans chaque observation pour\n# assurer la traçabilité et la reproductibilité des résultats.\nSOURCE_VERSION = "V26"\n\nID_COLUMNS = [\n    "societe",\n    "secteur",\n    "annee",\n    "type_comptes_resolu",\n    "statut_perimetre_is",\n]\nFINANCIAL_VARIABLES = [\n    "chiffre_affaires",\n    "ebit",\n    "resultat_financier",\n    "resultat_avant_impot",\n    "resultat_net",\n    "total_actif",\n    "capitaux_propres",\n    "total_dettes",\n    "dettes_financieres",\n    "tresorerie_equivalents",\n    "ebitda",\n    "immobilisations_corporelles",\n    "impot_differe",\n]\n\n\ndef normalize(text):\n    """Normalise les libellés sectoriels sans accents ni ponctuation."""\n    text = unicodedata.normalize("NFKD", str(text))\n    text = "".join(char for char in text if not unicodedata.combining(char))\n    return re.sub(r"[^a-z0-9]+", " ", text.lower()).strip()\n\n\ndef safe_ratio(numerator, denominator):\n    """Calcule un ratio en neutralisant les dénominateurs nuls ou quasi nuls."""\n    denominator = denominator.where(denominator.abs() > 1)\n    result = numerator / denominator\n    return result.replace([np.inf, -np.inf], np.nan)\n\n\ndef temporal_split(year):\n    """Attribue une année à l\'apprentissage, la validation ou au test final.\n\n    Le test 2023-2025 reste séparé pour simuler une prévision sur des périodes\n    futures. Il ne doit pas servir au choix des variables ou des paramètres.\n    """\n    if year <= 2019:\n        return "apprentissage"\n    if year <= 2022:\n        return "validation"\n    return "test_final"\n\n\ndef add_features(panel):\n    """Construit les variables dérivées utilisables par les futurs modèles."""\n    panel = panel.copy()\n    panel["version_source"] = SOURCE_VERSION\n    panel["secteur_normalise"] = panel["secteur"].map(normalize)\n    panel["est_banque"] = panel["secteur_normalise"].str.contains(\n        "banque|bancaire", regex=True, na=False\n    )\n    panel["qualite_perimetre"] = np.where(\n        panel["statut_perimetre_is"].isin(\n            [\n                "vérifié_par_rcai_moins_resultat_net",\n                "vérifié_par_impôt_du_pdf",\n            ]\n        ),\n        "haute",\n        "provisoire",\n    )\n\n    # Le logarithme signé réduit l\'écart d\'échelle entre petites et grandes\n    # entreprises, tout en tolérant les rares montants négatifs.\n    panel["taille_log_actif"] = np.sign(panel["total_actif"]) * np.log1p(\n        panel["total_actif"].abs()\n    )\n    panel["rentabilite_actif"] = safe_ratio(\n        panel["resultat_net"], panel["total_actif"]\n    )\n    panel["ratio_capitaux_propres"] = safe_ratio(\n        panel["capitaux_propres"], panel["total_actif"]\n    )\n    panel["ratio_dettes_financieres"] = safe_ratio(\n        panel["dettes_financieres"], panel["total_actif"]\n    )\n    panel["marge_ebit"] = safe_ratio(panel["ebit"], panel["chiffre_affaires"])\n    panel["marge_nette"] = safe_ratio(\n        panel["resultat_net"], panel["chiffre_affaires"]\n    )\n    # Variable conservée uniquement pour le diagnostic fiscal. Elle ne doit pas\n    # prédire l\'IS contemporain car elle contient directement l\'IS au numérateur.\n    panel["taux_effectif_observe"] = safe_ratio(\n        panel["is_mad"], panel["resultat_avant_impot"]\n    )\n\n    # Les retards sont calculés à périmètre constant pour ne jamais relier une\n    # observation sociale à une observation consolidée.\n    group = ["societe", "type_comptes_resolu"]\n    panel = panel.sort_values(group + ["annee"]).reset_index(drop=True)\n    for variable in [\n        "is_mad",\n        "chiffre_affaires",\n        "resultat_avant_impot",\n        "resultat_net",\n        "total_actif",\n        "capitaux_propres",\n    ]:\n        panel[f"{variable}_retard_1"] = panel.groupby(group)[variable].shift(1)\n        previous_year = panel.groupby(group)["annee"].shift(1)\n        # Le retard est annulé si deux exercices ne sont pas consécutifs.\n        panel.loc[\n            panel["annee"].sub(previous_year).ne(1), f"{variable}_retard_1"\n        ] = np.nan\n\n    for variable in [\n        "chiffre_affaires",\n        "resultat_avant_impot",\n        "resultat_net",\n        "total_actif",\n        "capitaux_propres",\n    ]:\n        panel[f"croissance_{variable}"] = safe_ratio(\n            panel[variable] - panel[f"{variable}_retard_1"],\n            panel[f"{variable}_retard_1"].abs(),\n        )\n\n    # Les indicateurs de manque permettent aux modèles compatibles de distinguer\n    # une valeur absente d\'une valeur économique égale à zéro.\n    for variable in FINANCIAL_VARIABLES:\n        panel[f"{variable}_manquant"] = panel[variable].isna().astype("int8")\n    panel["split_temporel_t"] = panel["annee"].map(temporal_split)\n    return panel\n\n\ndef make_forecast_dataset(panel):\n    """Associe chaque ligne de l\'année t à l\'IS observé exactement en t+1."""\n    current = panel.copy()\n    future = panel[\n        [\n            "societe",\n            "type_comptes_resolu",\n            "annee",\n            "is_mad",\n            "qualite_perimetre",\n        ]\n    ].copy()\n    # Décaler la clé d\'une année permet une jointure exacte, sans interpolation\n    # et sans utiliser par erreur une cible éloignée de plusieurs années.\n    future["annee"] = future["annee"] - 1\n    future.rename(\n        columns={\n            "is_mad": "is_cible_t_plus_1",\n            "qualite_perimetre": "qualite_cible_t_plus_1",\n        },\n        inplace=True,\n    )\n    forecast = current.merge(\n        future,\n        on=["societe", "type_comptes_resolu", "annee"],\n        how="inner",\n    )\n    forecast["annee_cible"] = forecast["annee"] + 1\n    forecast["split_temporel_cible"] = forecast["annee_cible"].map(temporal_split)\n    forecast["cible_disponible"] = forecast["is_cible_t_plus_1"].notna()\n    return forecast[forecast["cible_disponible"]].copy()\n\n\ndef main():\n    """Crée les échantillons, effectue les contrôles et exporte les résultats."""\n    panel = pd.read_excel(PANEL_FILE, sheet_name="Panel provisoire")\n    panel = panel.drop_duplicates(\n        ["societe", "annee", "type_comptes_resolu"], keep="first"\n    )\n    panel = add_features(panel)\n\n    # Plusieurs échantillons sont conservés pour étudier le compromis entre le\n    # nombre de variables exigées et le nombre d\'observations disponibles.\n    reference = panel.dropna(subset=["is_mad", "resultat_avant_impot"]).copy()\n    essential = panel.dropna(\n        subset=["is_mad", "resultat_avant_impot", "resultat_net", "total_actif"]\n    ).copy()\n    non_bank = panel[\n        ~panel["est_banque"]\n    ].dropna(\n        subset=[\n            "is_mad",\n            "chiffre_affaires",\n            "resultat_avant_impot",\n            "resultat_net",\n            "total_actif",\n            "capitaux_propres",\n        ]\n    ).copy()\n    high_confidence = panel[\n        panel["qualite_perimetre"].eq("haute")\n        & panel["resultat_avant_impot"].notna()\n    ].copy()\n    # Ce jeu constitue la base principale du futur travail de prédiction.\n    forecast = make_forecast_dataset(panel)\n\n    reference.to_csv(REFERENCE_CSV, index=False, encoding="utf-8-sig")\n    forecast.to_csv(FORECAST_CSV, index=False, encoding="utf-8-sig")\n\n    sample_rows = []\n    samples = {\n        "Référence contemporaine": reference,\n        "Essentiel contemporain": essential,\n        "Non bancaire 5 variables": non_bank,\n        "Haute confiance": high_confidence,\n        "Prévision réelle t+1": forecast,\n    }\n    for name, frame in samples.items():\n        year_column = "annee_cible" if name == "Prévision réelle t+1" else "annee"\n        sample_rows.append(\n            {\n                "echantillon": name,\n                "observations": len(frame),\n                "entreprises": frame["societe"].nunique(),\n                "annee_min": frame[year_column].min() if len(frame) else pd.NA,\n                "annee_max": frame[year_column].max() if len(frame) else pd.NA,\n                "apprentissage": (\n                    frame[\n                        (\n                            frame["split_temporel_cible"]\n                            if name == "Prévision réelle t+1"\n                            else frame["split_temporel_t"]\n                        ).eq("apprentissage")\n                    ].shape[0]\n                ),\n                "validation": (\n                    frame[\n                        (\n                            frame["split_temporel_cible"]\n                            if name == "Prévision réelle t+1"\n                            else frame["split_temporel_t"]\n                        ).eq("validation")\n                    ].shape[0]\n                ),\n                "test_final": (\n                    frame[\n                        (\n                            frame["split_temporel_cible"]\n                            if name == "Prévision réelle t+1"\n                            else frame["split_temporel_t"]\n                        ).eq("test_final")\n                    ].shape[0]\n                ),\n            }\n        )\n    sample_summary = pd.DataFrame(sample_rows)\n\n    # Contrôles explicites contre les doublons, les années non consécutives et\n    # les fuites d\'information.\n    controls = pd.DataFrame(\n        [\n            {\n                "controle": "Doublons société-année-type dans panel",\n                "valeur": panel.duplicated(\n                    ["societe", "annee", "type_comptes_resolu"]\n                ).sum(),\n                "statut": "OK",\n            },\n            {\n                "controle": "Observations panel",\n                "valeur": len(panel),\n                "statut": "Information",\n            },\n            {\n                "controle": "Cibles futures sans année consécutive",\n                "valeur": (\n                    forecast["annee_cible"] - forecast["annee"] != 1\n                ).sum(),\n                "statut": "OK",\n            },\n            {\n                "controle": "Fuite : taux effectif autorisé comme prédicteur contemporain",\n                "valeur": 0,\n                "statut": "INTERDIT",\n            },\n            {\n                "controle": "Années test final",\n                "valeur": "2023-2025",\n                "statut": "Défini",\n            },\n        ]\n    )\n\n    # Dictionnaire destiné à faciliter la lecture du classeur par l\'encadrant.\n    dictionary_rows = [\n        ("is_mad", "Cible contemporaine", "Montant annuel d\'IS en MAD"),\n        (\n            "is_cible_t_plus_1",\n            "Cible future",\n            "IS de l\'année suivante à prédire avec les informations de t",\n        ),\n        (\n            "resultat_avant_impot",\n            "Variable financière",\n            "Résultat avant impôt/RCAI en MAD",\n        ),\n        ("resultat_net", "Variable financière", "Résultat net en MAD"),\n        ("total_actif", "Variable financière", "Total actif en MAD"),\n        ("capitaux_propres", "Variable financière", "Capitaux propres en MAD"),\n        ("chiffre_affaires", "Variable financière", "Chiffre d\'affaires en MAD"),\n        (\n            "taille_log_actif",\n            "Variable dérivée",\n            "Transformation logarithmique signée du total actif",\n        ),\n        (\n            "rentabilite_actif",\n            "Ratio",\n            "Résultat net divisé par le total actif",\n        ),\n        (\n            "ratio_capitaux_propres",\n            "Ratio",\n            "Capitaux propres divisés par le total actif",\n        ),\n        (\n            "taux_effectif_observe",\n            "Diagnostic uniquement",\n            "IS/RCAI ; interdit comme prédicteur de l\'IS contemporain",\n        ),\n        (\n            "*_retard_1",\n            "Variable retardée",\n            "Valeur de l\'année précédente uniquement si les années sont consécutives",\n        ),\n        (\n            "*_manquant",\n            "Indicateur",\n            "1 lorsque la variable financière est absente, sinon 0",\n        ),\n        (\n            "split_temporel_t",\n            "Partition",\n            "Apprentissage <=2019, validation 2020-2022, test 2023-2025",\n        ),\n        (\n            "qualite_perimetre",\n            "Qualité",\n            "Haute si périmètre vérifié par identité fiscale ou impôt du PDF",\n        ),\n    ]\n    dictionary = pd.DataFrame(\n        dictionary_rows, columns=["variable", "categorie", "definition"]\n    )\n\n    methodology = pd.DataFrame(\n        {\n            "regle": [\n                "Version figée",\n                "Unité",\n                "Prévision contemporaine",\n                "Prévision future",\n                "Validation",\n                "Imputation",\n                "Banques",\n                "Fuite comptable",\n            ],\n            "description": [\n                "La base financière V15 est la source officielle de cette étape.",\n                "Tous les montants financiers sont exprimés en MAD.",\n                "IS(t) peut être expliqué par RCAI(t), mais ce scénario n\'est pas une vraie prévision anticipée.",\n                "Le jeu t+1 utilise uniquement les variables connues en t pour prédire IS(t+1).",\n                "Les années 2023-2025 sont réservées au test final.",\n                "Toute imputation devra être ajustée uniquement sur l\'apprentissage dans un pipeline ML.",\n                "Le chiffre d\'affaires n\'est pas imputé artificiellement aux banques ; utiliser le PNB dans une étude séparée.",\n                "Le taux effectif IS/RCAI et toute variable contenant directement la cible sont interdits comme prédicteurs contemporains.",\n            ],\n        }\n    )\n\n    with pd.ExcelWriter(OUTPUT_FILE, engine="openpyxl") as writer:\n        reference.to_excel(writer, sheet_name="Référence IS RCAI", index=False)\n        essential.to_excel(writer, sheet_name="Essentiel 3 variables", index=False)\n        non_bank.to_excel(writer, sheet_name="Non bancaire 5 var", index=False)\n        high_confidence.to_excel(writer, sheet_name="Haute confiance", index=False)\n        forecast.to_excel(writer, sheet_name="Prévision t plus 1", index=False)\n        sample_summary.to_excel(writer, sheet_name="Résumé échantillons", index=False)\n        dictionary.to_excel(writer, sheet_name="Dictionnaire", index=False)\n        controls.to_excel(writer, sheet_name="Contrôles", index=False)\n        methodology.to_excel(writer, sheet_name="Méthodologie", index=False)\n\n    print("Échantillons :")\n    print(sample_summary.to_string(index=False))\n    print("\\nContrôles :")\n    print(controls.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT_FILE}")\n    print(f"Créé : {REFERENCE_CSV}")\n    print(f"Créé : {FORECAST_CSV}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '35_statistiques_descriptives.py': '"""\nAnalyse statistique descriptive de la base destinée à la prédiction de l\'IS.\n\nCe script exploite les deux jeux préparés à l\'étape précédente :\n1. le jeu contemporain, dans lequel les variables de l\'année t expliquent l\'IS\n   de cette même année ;\n2. le jeu de prévision, dans lequel les informations disponibles à l\'année t\n   servent à prédire l\'IS de l\'année t+1.\n\nLes résultats sont exportés dans un classeur Excel et sous forme de graphiques.\nCette étape reste descriptive : aucune relation observée ici ne doit être\ninterprétée comme une relation causale.\n"""\n\nfrom pathlib import Path\nimport warnings\n\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport pandas as pd\nimport seaborn as sns\n\n\n# ---------------------------------------------------------------------------\n# 1. Chemins des fichiers d\'entrée et de sortie\n# ---------------------------------------------------------------------------\n# L\'utilisation de pathlib rend les chemins compatibles avec différents\n# systèmes d\'exploitation et évite de concaténer manuellement des chaînes.\nOUT = Path("data/output")\nFIG = OUT / "figures_statistiques_descriptives"\nREFERENCE = OUT / "modelisation_reference_t.csv"\nFORECAST = OUT / "prevision_is_t_plus_1.csv"\nWORKBOOK = OUT / "statistiques_descriptives_is.xlsx"\n\n# Libellés lisibles utilisés dans les tableaux et graphiques. Les noms\n# techniques d\'origine sont conservés en parallèle pour assurer la traçabilité.\nLABELS = {\n    "is_mad": "IS observé (MAD)",\n    "is_cible_t_plus_1": "IS cible t+1 (MAD)",\n    "chiffre_affaires": "Chiffre d\'affaires",\n    "resultat_avant_impot": "Résultat avant impôt",\n    "resultat_net": "Résultat net",\n    "ebit": "EBIT",\n    "ebitda": "EBITDA",\n    "resultat_financier": "Résultat financier",\n    "total_actif": "Total actif",\n    "capitaux_propres": "Capitaux propres",\n    "total_dettes": "Total dettes",\n    "dettes_financieres": "Dettes financières",\n    "tresorerie_equivalents": "Trésorerie et équivalents",\n    "immobilisations_corporelles": "Immobilisations corporelles",\n    "impot_differe": "Impôt différé",\n    "taille_log_actif": "Log signé du total actif",\n    "rentabilite_actif": "Rentabilité de l\'actif",\n    "ratio_capitaux_propres": "Ratio de capitaux propres",\n    "ratio_dettes_financieres": "Ratio de dettes financières",\n    "marge_ebit": "Marge EBIT",\n    "marge_nette": "Marge nette",\n    "is_mad_retard_1": "IS retardé d\'un an",\n}\n\n# Variables financières retenues pour l\'exploration descriptive. Une variable\n# absente d\'un fichier sera ignorée automatiquement dans la fonction main().\nCORE = [\n    "is_mad", "is_cible_t_plus_1", "chiffre_affaires",\n    "resultat_avant_impot", "resultat_net", "ebit", "ebitda",\n    "resultat_financier", "total_actif", "capitaux_propres",\n    "total_dettes", "dettes_financieres", "tresorerie_equivalents",\n    "immobilisations_corporelles", "impot_differe", "taille_log_actif",\n    "rentabilite_actif", "ratio_capitaux_propres",\n    "ratio_dettes_financieres", "marge_ebit", "marge_nette",\n    "is_mad_retard_1",\n]\n\n\ndef describe_numeric(df, variables, sample):\n    """Calcule les principaux indicateurs descriptifs des variables numériques.\n\n    Les valeurs infinies sont converties en valeurs manquantes. Elles peuvent\n    notamment apparaître lors du calcul d\'un ratio dont le dénominateur est nul.\n    La médiane et les quartiles complètent la moyenne, souvent sensible aux\n    grandes différences de taille entre sociétés cotées.\n    """\n    rows = []\n    for col in variables:\n        s = pd.to_numeric(df[col], errors="coerce").replace([np.inf, -np.inf], np.nan)\n        valid = s.dropna()\n        rows.append({\n            "echantillon": sample,\n            "variable": col,\n            "libelle": LABELS.get(col, col),\n            "n": len(valid),\n            "manquants": s.isna().sum(),\n            "taux_manquants_pct": 100 * s.isna().mean(),\n            "moyenne": valid.mean(),\n            "ecart_type": valid.std(),\n            "minimum": valid.min(),\n            "q1": valid.quantile(.25),\n            "mediane": valid.median(),\n            "q3": valid.quantile(.75),\n            "maximum": valid.max(),\n            "asymetrie": valid.skew(),\n        })\n    return pd.DataFrame(rows)\n\n\ndef outlier_table(df, variables, sample):\n    """Repère les valeurs extrêmes selon la règle de l\'intervalle interquartile.\n\n    Une observation est signalée lorsqu\'elle se situe en dessous de\n    Q1 - 1,5*IQR ou au-dessus de Q3 + 1,5*IQR. Elle n\'est pas supprimée :\n    dans les données financières, une valeur élevée peut être économiquement\n    réelle et correspondre à une entreprise de grande taille.\n    """\n    rows = []\n    for col in variables:\n        s = pd.to_numeric(df[col], errors="coerce").replace([np.inf, -np.inf], np.nan)\n        valid = s.dropna()\n        q1, q3 = valid.quantile(.25), valid.quantile(.75)\n        iqr = q3 - q1\n        low, high = q1 - 1.5 * iqr, q3 + 1.5 * iqr\n        n_out = ((valid < low) | (valid > high)).sum()\n        rows.append({\n            "echantillon": sample, "variable": col,\n            "borne_basse_iqr": low, "borne_haute_iqr": high,\n            "valeurs_extremes": n_out,\n            "taux_valeurs_extremes_pct": 100 * n_out / len(valid) if len(valid) else np.nan,\n            "decision": "Conserver; traitement dans le pipeline du modèle",\n        })\n    return pd.DataFrame(rows)\n\n\ndef correlations(df, variables, target, sample):\n    """Mesure l\'association monotone entre chaque variable et la cible.\n\n    Le coefficient de Spearman est préféré à celui de Pearson, car les montants\n    financiers sont généralement asymétriques et comportent des valeurs\n    extrêmes. La corrélation décrit une association, et non une causalité.\n    """\n    corr = df[variables].apply(pd.to_numeric, errors="coerce").corr(method="spearman")\n    result = corr[target].drop(target).sort_values(key=lambda x: x.abs(), ascending=False)\n    return pd.DataFrame({\n        "echantillon": sample,\n        "variable": result.index,\n        "libelle": [LABELS.get(x, x) for x in result.index],\n        "correlation_spearman_avec_cible": result.values,\n    }), corr\n\n\ndef annual_table(df, target, year_col, sample):\n    """Résume la distribution de l\'IS pour chaque année d\'observation/cible."""\n    return (df.groupby(year_col, dropna=False)[target]\n            .agg(observations="count", entreprises="size", moyenne="mean",\n                 mediane="median", ecart_type="std", minimum="min", maximum="max")\n            .reset_index().assign(echantillon=sample))\n\n\ndef sector_table(df, target, sample):\n    """Compare la distribution de l\'IS entre les secteurs d\'activité."""\n    # On privilégie le secteur normalisé pour éviter de séparer artificiellement\n    # deux libellés différents désignant le même secteur.\n    sector = "secteur_normalise" if "secteur_normalise" in df else "secteur"\n    return (df.groupby(sector, dropna=False)[target]\n            .agg(observations="count", moyenne="mean", mediane="median",\n                 ecart_type="std", minimum="min", maximum="max")\n            .reset_index().assign(echantillon=sample))\n\n\ndef coverage_table(df, sample, year_col="annee", split_col="split_temporel_t"):\n    """Présente la couverture temporelle et le découpage de modélisation.\n\n    Pour la prévision t+1, year_col et split_col correspondent obligatoirement\n    à l\'année de la cible future. Cela garantit que 2023-2025 constitue bien le\n    test final, indépendamment de l\'année des variables explicatives.\n    """\n    return pd.DataFrame([{\n        "echantillon": sample,\n        "observations": len(df),\n        "entreprises": df["societe"].nunique(),\n        "annee_min": int(df[year_col].min()),\n        "annee_max": int(df[year_col].max()),\n        "apprentissage": int((df[split_col] == "apprentissage").sum()),\n        "validation": int((df[split_col] == "validation").sum()),\n        "test_final": int((df[split_col] == "test_final").sum()),\n    }])\n\n\ndef save_figures(ref, pred, corr_pred, pred_vars):\n    """Produit les graphiques directement réutilisables dans le rapport."""\n    FIG.mkdir(parents=True, exist_ok=True)\n    sns.set_theme(style="whitegrid")\n\n    # La distribution permet de vérifier l\'asymétrie de la cible et d\'anticiper\n    # l\'intérêt éventuel d\'une transformation logarithmique lors du ML.\n    plt.figure(figsize=(9, 5))\n    sns.histplot(pred["is_cible_t_plus_1"], bins=35, kde=True)\n    plt.title("Distribution de l\'IS cible à t+1")\n    plt.xlabel("IS (MAD)")\n    plt.tight_layout()\n    plt.savefig(FIG / "01_distribution_is_t_plus_1.png", dpi=180)\n    plt.close()\n\n    # La médiane est représentée plutôt que la moyenne afin que la tendance\n    # annuelle soit moins dominée par quelques très grandes entreprises.\n    yearly = pred.groupby("annee_cible")["is_cible_t_plus_1"].median()\n    plt.figure(figsize=(10, 5))\n    yearly.plot(marker="o")\n    plt.title("Évolution de l\'IS médian par année cible")\n    plt.ylabel("IS médian (MAD)")\n    plt.xlabel("Année cible")\n    plt.tight_layout()\n    plt.savefig(FIG / "02_evolution_is_median.png", dpi=180)\n    plt.close()\n\n    # Pour garder une matrice lisible, seules les douze associations absolues\n    # les plus fortes avec la cible sont affichées dans le graphique.\n    top = corr_pred["is_cible_t_plus_1"].drop("is_cible_t_plus_1").abs().nlargest(12).index\n    heat_vars = ["is_cible_t_plus_1"] + list(top)\n    plt.figure(figsize=(11, 9))\n    sns.heatmap(corr_pred.loc[heat_vars, heat_vars], cmap="vlag", center=0,\n                vmin=-1, vmax=1, square=False)\n    plt.title("Corrélations de Spearman — prévision t+1")\n    plt.tight_layout()\n    plt.savefig(FIG / "03_matrice_correlations_t_plus_1.png", dpi=180)\n    plt.close()\n\n    # Une forte proportion de valeurs manquantes peut rendre une variable\n    # inutilisable, même si sa relation apparente avec l\'IS est intéressante.\n    missing = pred[pred_vars].isna().mean().mul(100).sort_values()\n    plt.figure(figsize=(10, 7))\n    missing.plot.barh()\n    plt.title("Taux de valeurs manquantes — variables de prévision")\n    plt.xlabel("Valeurs manquantes (%)")\n    plt.tight_layout()\n    plt.savefig(FIG / "04_valeurs_manquantes_t_plus_1.png", dpi=180)\n    plt.close()\n\n    # Le graphique sectoriel est limité aux dix secteurs les plus représentés.\n    # Les points extrêmes restent dans les données, mais sont masqués ici pour\n    # préserver la lisibilité des boîtes à moustaches.\n    tmp = pred.copy()\n    tmp["secteur_graphique"] = tmp["secteur_normalise"].fillna("Non renseigné")\n    top_sector = tmp["secteur_graphique"].value_counts().head(10).index\n    tmp = tmp[tmp["secteur_graphique"].isin(top_sector)]\n    order = tmp.groupby("secteur_graphique")["is_cible_t_plus_1"].median().sort_values().index\n    plt.figure(figsize=(11, 7))\n    sns.boxplot(data=tmp, y="secteur_graphique", x="is_cible_t_plus_1",\n                order=order, showfliers=False)\n    plt.title("IS cible à t+1 par secteur (10 secteurs les plus représentés)")\n    plt.xlabel("IS (MAD), valeurs extrêmes masquées dans le graphique")\n    plt.ylabel("")\n    plt.tight_layout()\n    plt.savefig(FIG / "05_is_par_secteur.png", dpi=180)\n    plt.close()\n\n\ndef main():\n    """Orchestre les calculs, les contrôles et les exports."""\n    # Chargement des bases figées à l\'étape de préparation des données.\n    ref = pd.read_csv(REFERENCE)\n    pred = pd.read_csv(FORECAST)\n\n    # On ne conserve que les variables effectivement présentes dans chaque jeu.\n    # Le jeu t+1 contient à la fois l\'IS courant (information disponible à t)\n    # et l\'IS futur, qui constitue la cible à prédire.\n    ref_vars = [x for x in CORE if x in ref.columns and x != "is_cible_t_plus_1"]\n    pred_vars = [x for x in CORE if x in pred.columns]\n\n    # Calcul séparé des statistiques afin de ne pas confondre une explication\n    # contemporaine avec une véritable prévision hors période.\n    desc = pd.concat([\n        describe_numeric(ref, ref_vars, "Contemporain t"),\n        describe_numeric(pred, pred_vars, "Prévision t+1"),\n    ], ignore_index=True)\n    outliers = pd.concat([\n        outlier_table(ref, ref_vars, "Contemporain t"),\n        outlier_table(pred, pred_vars, "Prévision t+1"),\n    ], ignore_index=True)\n    corr_ref_long, corr_ref = correlations(ref, ref_vars, "is_mad", "Contemporain t")\n    corr_pred_long, corr_pred = correlations(\n        pred, pred_vars, "is_cible_t_plus_1", "Prévision t+1")\n    corr_long = pd.concat([corr_ref_long, corr_pred_long], ignore_index=True)\n    annual = pd.concat([\n        annual_table(ref, "is_mad", "annee", "Contemporain t"),\n        annual_table(pred, "is_cible_t_plus_1", "annee_cible", "Prévision t+1"),\n    ], ignore_index=True)\n    sectors = pd.concat([\n        sector_table(ref, "is_mad", "Contemporain t"),\n        sector_table(pred, "is_cible_t_plus_1", "Prévision t+1"),\n    ], ignore_index=True)\n    coverage = pd.concat([\n        coverage_table(ref, "Contemporain t"),\n        coverage_table(pred, "Prévision t+1", "annee_cible", "split_temporel_cible"),\n    ], ignore_index=True)\n\n    # Contrôles de cohérence indispensables avant toute modélisation.\n    # Une clé unique représente une entreprise, une année et un type de comptes.\n    controls = pd.DataFrame([\n        ["Doublons clés contemporain",\n         int(ref.duplicated(["societe", "annee", "type_comptes_resolu"]).sum()), "OK"],\n        ["Doublons clés prévision",\n         int(pred.duplicated(["societe", "annee", "type_comptes_resolu"]).sum()), "OK"],\n        ["Cibles contemporaines manquantes", int(ref["is_mad"].isna().sum()), "OK"],\n        ["Cibles t+1 manquantes", int(pred["is_cible_t_plus_1"].isna().sum()), "OK"],\n        ["Valeurs extrêmes supprimées", 0, "Aucune suppression automatique"],\n        ["Corrélation retenue", "Spearman", "Robuste aux distributions asymétriques"],\n    ], columns=["controle", "valeur", "statut"])\n\n    # Cette feuille rend explicites les conventions méthodologiques pour que\n    # l\'analyse soit reproductible et compréhensible par un tiers.\n    methodology = pd.DataFrame([\n        ["Unité d\'analyse", "Entreprise-année-type de comptes"],\n        ["Cible principale", "IS de l\'année suivante (is_cible_t_plus_1)"],\n        ["Statistiques", "n, moyenne, écart-type, min, quartiles, médiane, max, asymétrie"],\n        ["Valeurs extrêmes", "Détection IQR; conservation à ce stade"],\n        ["Corrélations", "Coefficient de Spearman; résultat descriptif, non causal"],\n        ["Test final", "2023-2025; ne doit pas guider le choix des variables ou hyperparamètres"],\n        ["Fuite d\'information", "Le taux effectif contemporain reste exclu des prédicteurs"],\n    ], columns=["element", "regle"])\n\n    save_figures(ref, pred, corr_pred, pred_vars)\n\n    # Un seul classeur regroupe toutes les tables. Les noms de feuilles sont\n    # volontairement courts pour respecter la limite imposée par Excel.\n    with pd.ExcelWriter(WORKBOOK, engine="openpyxl") as writer:\n        coverage.to_excel(writer, sheet_name="Vue ensemble", index=False)\n        desc.to_excel(writer, sheet_name="Statistiques", index=False)\n        annual.to_excel(writer, sheet_name="Evolution annuelle", index=False)\n        sectors.to_excel(writer, sheet_name="Par secteur", index=False)\n        corr_long.to_excel(writer, sheet_name="Correlations cible", index=False)\n        corr_ref.to_excel(writer, sheet_name="Matrice corr t")\n        corr_pred.to_excel(writer, sheet_name="Matrice corr t+1")\n        outliers.to_excel(writer, sheet_name="Valeurs extremes", index=False)\n        controls.to_excel(writer, sheet_name="Controles", index=False)\n        methodology.to_excel(writer, sheet_name="Methodologie", index=False)\n\n    print("Créé :", WORKBOOK)\n    print("Créé :", FIG)\n    print("\\nCouverture :\\n", coverage.to_string(index=False))\n    print("\\nTop corrélations t+1 :\\n", corr_pred_long.head(10).to_string(index=False))\n    print("\\nVariables les plus manquantes t+1 :\\n",\n          desc[desc["echantillon"].eq("Prévision t+1")]\n          .sort_values("taux_manquants_pct", ascending=False)\n          [["variable", "n", "taux_manquants_pct"]].head(10).to_string(index=False))\n\n\n# Ce bloc empêche l\'exécution automatique de l\'analyse si le fichier est\n# simplement importé depuis un autre script ou un notebook.\nif __name__ == "__main__":\n    warnings.filterwarnings("ignore", category=RuntimeWarning)\n    main()\n',
    '36_modeles_reference_is.py': '"""\nModèles de référence pour prévoir l\'impôt sur les sociétés à l\'année t+1.\n\nProtocole :\n- apprentissage : années cibles <= 2019 ;\n- validation : années cibles 2020-2022 ;\n- test final : années cibles 2023-2025.\n\nLes hyperparamètres sont choisis uniquement avec la validation. Après ce choix,\nchaque modèle est réentraîné sur apprentissage + validation, puis évalué une\nseule fois sur le test final. Le modèle naïf IS(t+1) = IS(t) constitue le seuil\nminimal que les modèles de Machine Learning doivent dépasser.\n"""\n\nfrom pathlib import Path\nimport json\nimport warnings\n\nimport joblib\nimport numpy as np\nimport pandas as pd\nfrom sklearn.compose import ColumnTransformer, TransformedTargetRegressor\nfrom sklearn.ensemble import GradientBoostingRegressor, RandomForestRegressor\nfrom sklearn.impute import SimpleImputer\nfrom sklearn.linear_model import ElasticNet, Ridge\nfrom sklearn.metrics import (\n    mean_absolute_error,\n    mean_squared_error,\n    median_absolute_error,\n    r2_score,\n)\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder, RobustScaler\n\n\nOUT = Path("data/output")\nINPUT = OUT / "prevision_is_t_plus_1.csv"\nRESULTS_XLSX = OUT / "resultats_modeles_reference_is.xlsx"\nPREDICTIONS_CSV = OUT / "predictions_test_modeles_reference.csv"\nMODEL_DIR = OUT / "modeles_is"\nTARGET = "is_cible_t_plus_1"\nRANDOM_STATE = 42\n\n# Le noyau repose sur les informations les plus directement liées à la cible.\n# L\'IS à t est connu au moment retenu pour prévoir l\'année suivante.\nMAIN_NUMERIC = [\n    "is_mad",\n    "is_mad_retard_1",\n    "resultat_avant_impot",\n    "annee",\n]\n\n# L\'ensemble enrichi ajoute les variables financières, même partiellement\n# manquantes. L\'imputation et les indicateurs de manque sont appris sans le test.\nENRICHED_NUMERIC = MAIN_NUMERIC + [\n    "resultat_net",\n    "chiffre_affaires",\n    "total_actif",\n    "capitaux_propres",\n    "ebit",\n    "resultat_financier",\n    "dettes_financieres",\n    "tresorerie_equivalents",\n    "ebitda",\n    "immobilisations_corporelles",\n    "impot_differe",\n]\n\nCATEGORICAL = ["secteur_normalise", "type_comptes_resolu", "est_banque"]\n\n\ndef metrics(y_true, y_pred):\n    """Calcule des métriques complémentaires exprimées en MAD.\n\n    Le WAPE rapporte la somme des erreurs absolues à la somme de l\'IS observé.\n    Il est plus stable qu\'un MAPE lorsque certains montants d\'IS sont faibles.\n    """\n    y_pred = np.maximum(np.asarray(y_pred, dtype=float), 0)\n    y_true = np.asarray(y_true, dtype=float)\n    return {\n        "MAE_MAD": mean_absolute_error(y_true, y_pred),\n        "RMSE_MAD": np.sqrt(mean_squared_error(y_true, y_pred)),\n        "MedAE_MAD": median_absolute_error(y_true, y_pred),\n        "R2": r2_score(y_true, y_pred),\n        "WAPE_pct": 100 * np.abs(y_true - y_pred).sum() / np.abs(y_true).sum(),\n    }\n\n\ndef make_preprocessor(numeric, categorical):\n    """Crée les traitements appris exclusivement à partir des données fournies."""\n    numeric_pipe = Pipeline([\n        # La médiane est robuste aux montants financiers extrêmes. Un indicateur\n        # précise au modèle qu\'une valeur a été imputée.\n        ("imputation", SimpleImputer(strategy="median", add_indicator=True)),\n        ("echelle", RobustScaler()),\n    ])\n    categorical_pipe = Pipeline([\n        ("imputation", SimpleImputer(strategy="most_frequent")),\n        # handle_unknown évite une erreur si un secteur apparaît plus tard.\n        ("encodage", OneHotEncoder(handle_unknown="ignore", sparse_output=False)),\n    ])\n    return ColumnTransformer([\n        ("numerique", numeric_pipe, numeric),\n        ("categoriel", categorical_pipe, categorical),\n    ], remainder="drop")\n\n\ndef build_model(family, numeric, categorical, params, log_target):\n    """Assemble un pipeline de prétraitement et un algorithme de régression."""\n    if family == "Ridge":\n        estimator = Ridge(alpha=params["alpha"])\n    elif family == "ElasticNet":\n        estimator = ElasticNet(\n            alpha=params["alpha"],\n            l1_ratio=params["l1_ratio"],\n            max_iter=50_000,\n            random_state=RANDOM_STATE,\n        )\n    elif family == "RandomForest":\n        estimator = RandomForestRegressor(\n            n_estimators=400,\n            max_depth=params["max_depth"],\n            min_samples_leaf=params["min_samples_leaf"],\n            max_features=params["max_features"],\n            random_state=RANDOM_STATE,\n            n_jobs=-1,\n        )\n    elif family == "GradientBoosting":\n        estimator = GradientBoostingRegressor(\n            n_estimators=params["n_estimators"],\n            learning_rate=params["learning_rate"],\n            max_depth=params["max_depth"],\n            min_samples_leaf=params["min_samples_leaf"],\n            loss="huber",\n            random_state=RANDOM_STATE,\n        )\n    else:\n        raise ValueError(f"Famille inconnue : {family}")\n\n    pipeline = Pipeline([\n        ("preparation", make_preprocessor(numeric, categorical)),\n        ("modele", estimator),\n    ])\n    if log_target:\n        # La transformation limite la domination des très grandes entreprises.\n        # expm1 remet ensuite automatiquement les prédictions en MAD.\n        return TransformedTargetRegressor(\n            regressor=pipeline, func=np.log1p, inverse_func=np.expm1\n        )\n    return pipeline\n\n\ndef configurations():\n    """Génère une grille volontairement limitée pour éviter le surajustement."""\n    configs = []\n    feature_sets = {\n        "noyau": MAIN_NUMERIC,\n        "enrichi": ENRICHED_NUMERIC,\n    }\n    for feature_name, numeric in feature_sets.items():\n        for log_target in [False, True]:\n            for alpha in [0.1, 1.0, 10.0, 100.0]:\n                configs.append(("Ridge", feature_name, numeric, log_target, {"alpha": alpha}))\n            for alpha in [0.001, 0.01, 0.1]:\n                for l1_ratio in [0.2, 0.5, 0.8]:\n                    configs.append((\n                        "ElasticNet", feature_name, numeric, log_target,\n                        {"alpha": alpha, "l1_ratio": l1_ratio},\n                    ))\n\n    # Les arbres utilisent l\'ensemble enrichi : ils peuvent apprendre des\n    # relations non linéaires et exploiter les indicateurs de valeurs manquantes.\n    for log_target in [False, True]:\n        for depth in [3, 5, None]:\n            for leaf in [3, 8, 15]:\n                configs.append((\n                    "RandomForest", "enrichi", ENRICHED_NUMERIC, log_target,\n                    {"max_depth": depth, "min_samples_leaf": leaf,\n                     "max_features": 0.7},\n                ))\n        for estimators in [100, 250]:\n            for depth in [1, 2]:\n                configs.append((\n                    "GradientBoosting", "enrichi", ENRICHED_NUMERIC, log_target,\n                    {"n_estimators": estimators, "learning_rate": 0.03,\n                     "max_depth": depth, "min_samples_leaf": 8},\n                ))\n    return configs\n\n\ndef main():\n    """Sélectionne les modèles sur validation et produit l\'évaluation finale."""\n    data = pd.read_csv(INPUT)\n    data = data.dropna(subset=[TARGET]).copy()\n\n    # Conversion explicite de l\'indicateur bancaire en catégorie lisible.\n    data["est_banque"] = data["est_banque"].astype(str)\n    numeric_available = [x for x in ENRICHED_NUMERIC if x in data.columns]\n    categorical_available = [x for x in CATEGORICAL if x in data.columns]\n\n    train = data[data["split_temporel_cible"].eq("apprentissage")].copy()\n    validation = data[data["split_temporel_cible"].eq("validation")].copy()\n    test = data[data["split_temporel_cible"].eq("test_final")].copy()\n\n    validation_rows = []\n    fitted_candidates = []\n    for index, (family, feature_name, numeric, log_target, params) in enumerate(\n        configurations(), start=1\n    ):\n        numeric = [x for x in numeric if x in numeric_available]\n        features = numeric + categorical_available\n        model = build_model(\n            family, numeric, categorical_available, params, log_target\n        )\n        model.fit(train[features], train[TARGET])\n        prediction = np.maximum(model.predict(validation[features]), 0)\n        row = {\n            "modele": family,\n            "jeu_variables": feature_name,\n            "cible_logarithmique": log_target,\n            "parametres": json.dumps(params, ensure_ascii=False),\n            **metrics(validation[TARGET], prediction),\n        }\n        validation_rows.append(row)\n        fitted_candidates.append((row, numeric, model))\n\n    # Le naïf est aussi mesuré sur la validation. Il ne participe pas au réglage\n    # des hyperparamètres, mais fournit le seuil à dépasser dès cette étape.\n    validation_rows.append({\n        "modele": "Naif_IS_t",\n        "jeu_variables": "IS courant uniquement",\n        "cible_logarithmique": False,\n        "parametres": "{}",\n        **metrics(validation[TARGET], validation["is_mad"]),\n    })\n    validation_results = pd.DataFrame(validation_rows).sort_values("MAE_MAD")\n\n    # Un seul réglage est retenu par famille sur la base de la MAE de validation.\n    best_rows = (\n        validation_results[\n            ~validation_results["modele"].eq("Naif_IS_t")\n        ].sort_values("MAE_MAD")\n        .groupby("modele", as_index=False)\n        .first()\n    )\n\n    train_validation = pd.concat([train, validation], ignore_index=True)\n    final_rows = []\n    prediction_table = test[\n        ["societe", "annee", "annee_cible", TARGET, "secteur_normalise"]\n    ].copy()\n\n    # Modèle naïf : aucune estimation de paramètre et aucune imputation.\n    naive_prediction = test["is_mad"].clip(lower=0)\n    final_rows.append({\n        "modele": "Naif_IS_t",\n        "jeu_variables": "IS courant uniquement",\n        "cible_logarithmique": False,\n        "parametres": "{}",\n        **metrics(test[TARGET], naive_prediction),\n    })\n    prediction_table["prediction_Naif_IS_t"] = naive_prediction.values\n\n    MODEL_DIR.mkdir(parents=True, exist_ok=True)\n    for _, selected in best_rows.iterrows():\n        family = selected["modele"]\n        params = json.loads(selected["parametres"])\n        feature_name = selected["jeu_variables"]\n        numeric = (\n            [x for x in MAIN_NUMERIC if x in numeric_available]\n            if feature_name == "noyau"\n            else numeric_available\n        )\n        features = numeric + categorical_available\n        model = build_model(\n            family, numeric, categorical_available, params,\n            bool(selected["cible_logarithmique"]),\n        )\n        model.fit(train_validation[features], train_validation[TARGET])\n        prediction = np.maximum(model.predict(test[features]), 0)\n        final_rows.append({\n            "modele": family,\n            "jeu_variables": feature_name,\n            "cible_logarithmique": bool(selected["cible_logarithmique"]),\n            "parametres": selected["parametres"],\n            "MAE_validation_MAD": selected["MAE_MAD"],\n            **metrics(test[TARGET], prediction),\n        })\n        prediction_table[f"prediction_{family}"] = prediction\n        joblib.dump(\n            {"modele": model, "variables": features, "cible": TARGET},\n            MODEL_DIR / f"{family.lower()}_is_t_plus_1.joblib",\n        )\n\n    final_results = pd.DataFrame(final_rows).sort_values("MAE_MAD")\n\n    # Diagnostics par année et par secteur pour le meilleur modèle ML.\n    best_ml = final_results[~final_results["modele"].eq("Naif_IS_t")].iloc[0]["modele"]\n    prediction_table["erreur_absolue_meilleur_ml"] = np.abs(\n        prediction_table[TARGET] - prediction_table[f"prediction_{best_ml}"]\n    )\n    by_year = (\n        prediction_table.groupby("annee_cible")\n        .agg(\n            observations=(TARGET, "size"),\n            IS_moyen=(TARGET, "mean"),\n            MAE=("erreur_absolue_meilleur_ml", "mean"),\n        )\n        .reset_index()\n    )\n    by_sector = (\n        prediction_table.groupby("secteur_normalise")\n        .agg(\n            observations=(TARGET, "size"),\n            IS_moyen=(TARGET, "mean"),\n            MAE=("erreur_absolue_meilleur_ml", "mean"),\n        )\n        .reset_index()\n        .sort_values("observations", ascending=False)\n    )\n\n    controls = pd.DataFrame([\n        ["Observations apprentissage", len(train), "OK"],\n        ["Observations validation", len(validation), "OK"],\n        ["Observations test final", len(test), "OK"],\n        ["Chevauchement temporel", 0, "OK"],\n        ["Critère de sélection", "MAE validation", "Test non utilisé"],\n        ["Modèle naïf", "IS(t+1)=IS(t)", "Référence obligatoire"],\n        ["Meilleur modèle ML sur test", best_ml, "Résultat hors échantillon"],\n    ], columns=["controle", "valeur", "statut"])\n\n    with pd.ExcelWriter(RESULTS_XLSX, engine="openpyxl") as writer:\n        final_results.to_excel(writer, sheet_name="Resultats test", index=False)\n        validation_results.to_excel(\n            writer, sheet_name="Tous essais validation", index=False\n        )\n        best_rows.to_excel(writer, sheet_name="Selection validation", index=False)\n        by_year.to_excel(writer, sheet_name="Performance par annee", index=False)\n        by_sector.to_excel(writer, sheet_name="Performance secteur", index=False)\n        controls.to_excel(writer, sheet_name="Controles", index=False)\n    prediction_table.to_csv(PREDICTIONS_CSV, index=False, encoding="utf-8-sig")\n\n    print("Résultats finaux sur le test 2023-2025 :")\n    print(final_results.to_string(index=False))\n    print(f"\\nCréé : {RESULTS_XLSX}")\n    print(f"Créé : {PREDICTIONS_CSV}")\n    print(f"Créé : {MODEL_DIR}")\n\n\nif __name__ == "__main__":\n    warnings.filterwarnings("ignore")\n    main()\n',
    '37_analyse_erreurs_et_delta_is.py': '"""\nAnalyse des erreurs et modélisation de la variation annuelle de l\'IS.\n\nAu lieu de prédire directement le niveau futur, cette étape cherche à prévoir :\n    delta_IS(t+1) = IS(t+1) - IS(t)\n\nLa prévision finale est reconstruite par :\n    IS_prédit(t+1) = max(0, IS(t) + delta_IS_prédit)\n\nLes réglages sont choisis sur 2020-2022. Le test 2023-2025 reste réservé à\nl\'évaluation finale et ne participe jamais au choix des hyperparamètres.\n"""\n\nfrom pathlib import Path\nimport json\nimport warnings\n\nimport joblib\nimport numpy as np\nimport pandas as pd\nfrom sklearn.compose import ColumnTransformer\nfrom sklearn.ensemble import GradientBoostingRegressor, RandomForestRegressor\nfrom sklearn.impute import SimpleImputer\nfrom sklearn.linear_model import ElasticNet, Ridge\nfrom sklearn.metrics import (\n    mean_absolute_error,\n    mean_squared_error,\n    median_absolute_error,\n    r2_score,\n)\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder, RobustScaler\n\n\nOUT = Path("data/output")\nINPUT = OUT / "prevision_is_t_plus_1.csv"\nOUTPUT_XLSX = OUT / "analyse_erreurs_et_modeles_delta_is.xlsx"\nOUTPUT_PREDICTIONS = OUT / "predictions_test_delta_is.csv"\nOUTPUT_MODEL = OUT / "modeles_is" / "meilleur_modele_delta_is.joblib"\nTARGET = "is_cible_t_plus_1"\nDELTA = "delta_is_cible"\nRANDOM_STATE = 42\n\n# Variables disponibles à la fin de l\'année t. Les taux de croissance et ratios\n# décrivent la dynamique récente susceptible d\'expliquer une variation de l\'IS.\nNUMERIC = [\n    "is_mad",\n    "is_mad_retard_1",\n    "resultat_avant_impot",\n    "resultat_avant_impot_retard_1",\n    "croissance_resultat_avant_impot",\n    "resultat_net",\n    "resultat_net_retard_1",\n    "croissance_resultat_net",\n    "chiffre_affaires",\n    "chiffre_affaires_retard_1",\n    "croissance_chiffre_affaires",\n    "total_actif",\n    "total_actif_retard_1",\n    "croissance_total_actif",\n    "capitaux_propres",\n    "capitaux_propres_retard_1",\n    "croissance_capitaux_propres",\n    "ebit",\n    "resultat_financier",\n    "taille_log_actif",\n    "rentabilite_actif",\n    "ratio_capitaux_propres",\n    "marge_ebit",\n    "marge_nette",\n    "taux_effectif_observe",\n    "annee",\n]\nCATEGORICAL = ["secteur_normalise", "type_comptes_resolu", "est_banque"]\n\n\ndef score_level(y_true, predicted_level):\n    """Évalue la prévision finale du niveau d\'IS, toujours exprimée en MAD."""\n    prediction = np.maximum(np.asarray(predicted_level, dtype=float), 0)\n    truth = np.asarray(y_true, dtype=float)\n    return {\n        "MAE_MAD": mean_absolute_error(truth, prediction),\n        "RMSE_MAD": np.sqrt(mean_squared_error(truth, prediction)),\n        "MedAE_MAD": median_absolute_error(truth, prediction),\n        "R2": r2_score(truth, prediction),\n        "WAPE_pct": 100 * np.abs(truth - prediction).sum() / np.abs(truth).sum(),\n    }\n\n\ndef preprocessor(numeric, categorical):\n    """Impute, met à l\'échelle et encode sans utiliser les données futures."""\n    return ColumnTransformer([\n        (\n            "numerique",\n            Pipeline([\n                ("imputation", SimpleImputer(strategy="median", add_indicator=True)),\n                ("echelle", RobustScaler()),\n            ]),\n            numeric,\n        ),\n        (\n            "categoriel",\n            Pipeline([\n                ("imputation", SimpleImputer(strategy="most_frequent")),\n                ("encodage", OneHotEncoder(handle_unknown="ignore", sparse_output=False)),\n            ]),\n            categorical,\n        ),\n    ])\n\n\ndef make_model(family, numeric, categorical, params):\n    """Crée un pipeline complet pour une famille et un réglage donnés."""\n    if family == "Ridge_delta":\n        estimator = Ridge(alpha=params["alpha"])\n    elif family == "ElasticNet_delta":\n        estimator = ElasticNet(\n            alpha=params["alpha"],\n            l1_ratio=params["l1_ratio"],\n            max_iter=50_000,\n            random_state=RANDOM_STATE,\n        )\n    elif family == "RandomForest_delta":\n        estimator = RandomForestRegressor(\n            n_estimators=500,\n            max_depth=params["max_depth"],\n            min_samples_leaf=params["min_samples_leaf"],\n            max_features=params["max_features"],\n            random_state=RANDOM_STATE,\n            n_jobs=-1,\n        )\n    elif family == "GradientBoosting_delta":\n        estimator = GradientBoostingRegressor(\n            n_estimators=params["n_estimators"],\n            learning_rate=params["learning_rate"],\n            max_depth=params["max_depth"],\n            min_samples_leaf=params["min_samples_leaf"],\n            loss="huber",\n            random_state=RANDOM_STATE,\n        )\n    else:\n        raise ValueError(f"Famille inconnue : {family}")\n    return Pipeline([\n        ("preparation", preprocessor(numeric, categorical)),\n        ("modele", estimator),\n    ])\n\n\ndef grid():\n    """Grille compacte adaptée à la taille limitée de l\'échantillon."""\n    settings = []\n    for alpha in [0.1, 1, 10, 100, 1_000]:\n        settings.append(("Ridge_delta", {"alpha": alpha}))\n    for alpha in [0.001, 0.01, 0.1, 1.0]:\n        for ratio in [0.2, 0.5, 0.8]:\n            settings.append((\n                "ElasticNet_delta", {"alpha": alpha, "l1_ratio": ratio}\n            ))\n    for depth in [2, 3, 5]:\n        for leaf in [5, 10, 20]:\n            settings.append((\n                "RandomForest_delta",\n                {"max_depth": depth, "min_samples_leaf": leaf, "max_features": 0.7},\n            ))\n    for estimators in [100, 250]:\n        for depth in [1, 2]:\n            settings.append((\n                "GradientBoosting_delta",\n                {"n_estimators": estimators, "learning_rate": 0.03,\n                 "max_depth": depth, "min_samples_leaf": 10},\n            ))\n    return settings\n\n\ndef error_diagnostics(frame, prediction_column):\n    """Produit les diagnostics du modèle naïf ou d\'une prévision sélectionnée."""\n    work = frame.copy()\n    work["erreur_signee"] = work[prediction_column] - work[TARGET]\n    work["erreur_absolue"] = work["erreur_signee"].abs()\n    work["sous_prediction"] = work["erreur_signee"].lt(0)\n\n    by_year = work.groupby("annee_cible").agg(\n        observations=(TARGET, "size"),\n        IS_moyen=(TARGET, "mean"),\n        erreur_moyenne_signee=("erreur_signee", "mean"),\n        MAE=("erreur_absolue", "mean"),\n        taux_sous_prediction_pct=("sous_prediction", lambda x: 100 * x.mean()),\n    ).reset_index()\n    by_sector = work.groupby("secteur_normalise").agg(\n        observations=(TARGET, "size"),\n        IS_moyen=(TARGET, "mean"),\n        erreur_moyenne_signee=("erreur_signee", "mean"),\n        MAE=("erreur_absolue", "mean"),\n        taux_sous_prediction_pct=("sous_prediction", lambda x: 100 * x.mean()),\n    ).reset_index().sort_values(["observations", "MAE"], ascending=[False, False])\n    by_bank = work.groupby("est_banque").agg(\n        observations=(TARGET, "size"),\n        IS_moyen=(TARGET, "mean"),\n        erreur_moyenne_signee=("erreur_signee", "mean"),\n        MAE=("erreur_absolue", "mean"),\n    ).reset_index()\n    by_company = work.groupby("societe").agg(\n        observations=(TARGET, "size"),\n        IS_moyen=(TARGET, "mean"),\n        erreur_moyenne_signee=("erreur_signee", "mean"),\n        MAE=("erreur_absolue", "mean"),\n    ).reset_index().sort_values("MAE", ascending=False)\n    worst = work.sort_values("erreur_absolue", ascending=False).head(25)\n    return by_year, by_sector, by_bank, by_company, worst\n\n\ndef main():\n    """Sélectionne le modèle delta et compare sa prévision au modèle naïf."""\n    data = pd.read_csv(INPUT).dropna(subset=[TARGET, "is_mad"]).copy()\n    data["est_banque"] = data["est_banque"].astype(str)\n    data[DELTA] = data[TARGET] - data["is_mad"]\n    numeric = [x for x in NUMERIC if x in data.columns]\n    categorical = [x for x in CATEGORICAL if x in data.columns]\n    features = numeric + categorical\n\n    train = data[data["split_temporel_cible"].eq("apprentissage")].copy()\n    validation = data[data["split_temporel_cible"].eq("validation")].copy()\n    test = data[data["split_temporel_cible"].eq("test_final")].copy()\n\n    validation_rows = [{\n        "modele": "Naif_delta_zero",\n        "parametres": "{}",\n        **score_level(validation[TARGET], validation["is_mad"]),\n    }]\n    for family, params in grid():\n        model = make_model(family, numeric, categorical, params)\n        model.fit(train[features], train[DELTA])\n        predicted_delta = model.predict(validation[features])\n        predicted_level = validation["is_mad"].to_numpy() + predicted_delta\n        validation_rows.append({\n            "modele": family,\n            "parametres": json.dumps(params, ensure_ascii=False),\n            **score_level(validation[TARGET], predicted_level),\n        })\n\n    validation_results = pd.DataFrame(validation_rows).sort_values("MAE_MAD")\n    best_candidate = validation_results[\n        ~validation_results["modele"].eq("Naif_delta_zero")\n    ].iloc[0]\n\n    # Réentraînement du meilleur réglage avec toutes les données antérieures au\n    # test, sans modifier le choix après observation de 2023-2025.\n    train_validation = pd.concat([train, validation], ignore_index=True)\n    best_model = make_model(\n        best_candidate["modele"],\n        numeric,\n        categorical,\n        json.loads(best_candidate["parametres"]),\n    )\n    best_model.fit(train_validation[features], train_validation[DELTA])\n    predicted_delta = best_model.predict(test[features])\n    predicted_level = np.maximum(test["is_mad"].to_numpy() + predicted_delta, 0)\n\n    test_predictions = test[\n        [\n            "societe", "secteur_normalise", "est_banque", "annee",\n            "annee_cible", "is_mad", TARGET,\n        ]\n    ].copy()\n    test_predictions["delta_reel"] = test[DELTA].to_numpy()\n    test_predictions["prediction_naive"] = test["is_mad"].to_numpy()\n    test_predictions["delta_predit"] = predicted_delta\n    test_predictions["prediction_delta"] = predicted_level\n\n    final_results = pd.DataFrame([\n        {\n            "modele": "Naif_IS_t",\n            "selection": "Référence sans réglage",\n            **score_level(test[TARGET], test_predictions["prediction_naive"]),\n        },\n        {\n            "modele": best_candidate["modele"],\n            "selection": "Meilleur sur validation 2020-2022",\n            "parametres": best_candidate["parametres"],\n            "MAE_validation_MAD": best_candidate["MAE_MAD"],\n            **score_level(test[TARGET], test_predictions["prediction_delta"]),\n        },\n    ]).sort_values("MAE_MAD")\n\n    naive_diag = error_diagnostics(test_predictions, "prediction_naive")\n    delta_diag = error_diagnostics(test_predictions, "prediction_delta")\n    delta_stats = data.groupby("split_temporel_cible")[DELTA].agg(\n        observations="count", moyenne="mean", ecart_type="std",\n        minimum="min", q1=lambda x: x.quantile(.25), mediane="median",\n        q3=lambda x: x.quantile(.75), maximum="max",\n    ).reset_index()\n\n    controls = pd.DataFrame([\n        ["Cible du modèle", "IS(t+1)-IS(t)", "Définie"],\n        ["Critère de sélection", "MAE du niveau final sur validation", "Correct"],\n        ["Observations apprentissage", len(train), "OK"],\n        ["Observations validation", len(validation), "OK"],\n        ["Observations test", len(test), "OK"],\n        ["Meilleur réglage", best_candidate["modele"], "Choisi sans le test"],\n    ], columns=["controle", "valeur", "statut"])\n\n    OUTPUT_MODEL.parent.mkdir(parents=True, exist_ok=True)\n    joblib.dump(\n        {"modele": best_model, "variables": features, "cible": DELTA},\n        OUTPUT_MODEL,\n    )\n    test_predictions.to_csv(\n        OUTPUT_PREDICTIONS, index=False, encoding="utf-8-sig"\n    )\n    with pd.ExcelWriter(OUTPUT_XLSX, engine="openpyxl") as writer:\n        final_results.to_excel(writer, sheet_name="Comparaison test", index=False)\n        validation_results.to_excel(writer, sheet_name="Essais validation", index=False)\n        delta_stats.to_excel(writer, sheet_name="Statistiques delta", index=False)\n        naive_diag[0].to_excel(writer, sheet_name="Naif par annee", index=False)\n        naive_diag[1].to_excel(writer, sheet_name="Naif par secteur", index=False)\n        naive_diag[2].to_excel(writer, sheet_name="Naif banques", index=False)\n        naive_diag[3].to_excel(writer, sheet_name="Naif entreprises", index=False)\n        naive_diag[4].to_excel(writer, sheet_name="Pires erreurs naif", index=False)\n        delta_diag[0].to_excel(writer, sheet_name="Delta par annee", index=False)\n        delta_diag[1].to_excel(writer, sheet_name="Delta par secteur", index=False)\n        delta_diag[2].to_excel(writer, sheet_name="Delta banques", index=False)\n        delta_diag[3].to_excel(writer, sheet_name="Delta entreprises", index=False)\n        delta_diag[4].to_excel(writer, sheet_name="Pires erreurs delta", index=False)\n        controls.to_excel(writer, sheet_name="Controles", index=False)\n\n    print("Comparaison finale 2023-2025 :")\n    print(final_results.to_string(index=False))\n    print("\\nStatistiques de variation :")\n    print(delta_stats.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT_XLSX}")\n    print(f"Créé : {OUTPUT_PREDICTIONS}")\n    print(f"Créé : {OUTPUT_MODEL}")\n\n\nif __name__ == "__main__":\n    warnings.filterwarnings("ignore")\n    main()\n',
    '38_validation_temporelle_hybride.py': '"""\nValidation temporelle glissante d\'une stratégie banques/non-banques.\n\nPour chaque année cible de 2016 à 2022, le modèle delta est réentraîné uniquement\nsur les années antérieures, puis comparé à la prévision naïve. Le choix entre\nles deux méthodes est effectué séparément pour les banques et les non-banques\nà partir de ces seuls résultats historiques.\n\nL\'évaluation 2023-2025 de la stratégie hybride est une analyse de sensibilité :\nle résultat principal reste celui du modèle delta global présenté à l\'étape 37.\n"""\n\nfrom importlib.util import module_from_spec, spec_from_file_location\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\n\nOUT = Path("data/output")\nINPUT = OUT / "prevision_is_t_plus_1.csv"\nOUTPUT = OUT / "validation_temporelle_et_strategie_hybride.xlsx"\nPREDICTIONS = OUT / "predictions_test_strategie_hybride.csv"\nTARGET = "is_cible_t_plus_1"\nDELTA = "delta_is_cible"\nBACKTEST_YEARS = range(2016, 2023)\n\n# Réutilisation des fonctions documentées de l\'étape 37 afin que les traitements\n# et l\'algorithme soient strictement identiques entre les deux analyses.\nspec = spec_from_file_location("delta_module", Path("37_analyse_erreurs_et_delta_is.py"))\ndelta_module = module_from_spec(spec)\nspec.loader.exec_module(delta_module)\n\nBEST_PARAMS = {\n    "n_estimators": 100,\n    "learning_rate": 0.03,\n    "max_depth": 1,\n    "min_samples_leaf": 10,\n}\n\n\ndef metric_rows(frame, period):\n    """Calcule la MAE et le WAPE par groupe et par méthode de prévision."""\n    rows = []\n    for bank_value, group in frame.groupby("est_banque"):\n        label = "Banques" if str(bank_value).lower() == "true" else "Non-banques"\n        for method, column in [\n            ("Naif_IS_t", "prediction_naive"),\n            ("GradientBoosting_delta", "prediction_delta"),\n        ]:\n            error = np.abs(group[TARGET] - group[column])\n            rows.append({\n                "periode": period,\n                "groupe": label,\n                "methode": method,\n                "observations": len(group),\n                "MAE_MAD": error.mean(),\n                "WAPE_pct": 100 * error.sum() / group[TARGET].abs().sum(),\n            })\n    return rows\n\n\ndef main():\n    """Exécute le backtest, fixe la règle historique et l\'applique au test."""\n    data = pd.read_csv(INPUT).dropna(subset=[TARGET, "is_mad"]).copy()\n    data["est_banque"] = data["est_banque"].astype(str)\n    data[DELTA] = data[TARGET] - data["is_mad"]\n    numeric = [x for x in delta_module.NUMERIC if x in data.columns]\n    categorical = [x for x in delta_module.CATEGORICAL if x in data.columns]\n    features = numeric + categorical\n\n    fold_predictions = []\n    fold_metrics = []\n    for year in BACKTEST_YEARS:\n        train = data[data["annee_cible"].lt(year)].copy()\n        fold = data[data["annee_cible"].eq(year)].copy()\n        if len(train) < 50 or fold.empty:\n            continue\n\n        # Le modèle ne voit jamais l\'année qu\'il doit prédire.\n        model = delta_module.make_model(\n            "GradientBoosting_delta", numeric, categorical, BEST_PARAMS\n        )\n        model.fit(train[features], train[DELTA])\n        fold["prediction_naive"] = fold["is_mad"].clip(lower=0)\n        fold["delta_predit"] = model.predict(fold[features])\n        fold["prediction_delta"] = np.maximum(\n            fold["is_mad"] + fold["delta_predit"], 0\n        )\n        fold_predictions.append(fold)\n        fold_metrics.extend(metric_rows(fold, str(year)))\n\n    backtest = pd.concat(fold_predictions, ignore_index=True)\n    metrics_by_fold = pd.DataFrame(fold_metrics)\n\n    # Agrégation sur toutes les prédictions hors échantillon historiques. La\n    # méthode ayant la plus faible MAE est retenue indépendamment dans chaque\n    # groupe, avant de consulter les performances finales de la stratégie.\n    historical_rows = metric_rows(backtest, "Agrégé 2016-2022")\n    historical = pd.DataFrame(historical_rows)\n    rule = (\n        historical.sort_values("MAE_MAD")\n        .groupby("groupe", as_index=False)\n        .first()[["groupe", "methode", "MAE_MAD", "WAPE_pct"]]\n        .rename(columns={"methode": "methode_retenue"})\n    )\n\n    # Modèle final entraîné sur toutes les années antérieures au test.\n    train_final = data[data["annee_cible"].le(2022)].copy()\n    test = data[data["annee_cible"].ge(2023)].copy()\n    final_model = delta_module.make_model(\n        "GradientBoosting_delta", numeric, categorical, BEST_PARAMS\n    )\n    final_model.fit(train_final[features], train_final[DELTA])\n    test["prediction_naive"] = test["is_mad"].clip(lower=0)\n    test["delta_predit"] = final_model.predict(test[features])\n    test["prediction_delta"] = np.maximum(\n        test["is_mad"] + test["delta_predit"], 0\n    )\n    test["groupe"] = np.where(\n        test["est_banque"].str.lower().eq("true"), "Banques", "Non-banques"\n    )\n    rule_map = rule.set_index("groupe")["methode_retenue"].to_dict()\n    test["methode_hybride"] = test["groupe"].map(rule_map)\n    test["prediction_hybride"] = np.where(\n        test["methode_hybride"].eq("GradientBoosting_delta"),\n        test["prediction_delta"],\n        test["prediction_naive"],\n    )\n\n    comparison = []\n    for method, column in [\n        ("Naif_IS_t", "prediction_naive"),\n        ("GradientBoosting_delta", "prediction_delta"),\n        ("Strategie_hybride_historique", "prediction_hybride"),\n    ]:\n        values = delta_module.score_level(test[TARGET], test[column])\n        comparison.append({"methode": method, **values})\n    comparison = pd.DataFrame(comparison).sort_values("MAE_MAD")\n\n    test_group_rows = []\n    for group_name, group in test.groupby("groupe"):\n        for method, column in [\n            ("Naif_IS_t", "prediction_naive"),\n            ("GradientBoosting_delta", "prediction_delta"),\n            ("Strategie_hybride_historique", "prediction_hybride"),\n        ]:\n            test_group_rows.append({\n                "groupe": group_name,\n                "methode": method,\n                "observations": len(group),\n                **delta_module.score_level(group[TARGET], group[column]),\n            })\n    test_groups = pd.DataFrame(test_group_rows)\n\n    controls = pd.DataFrame([\n        ["Années du backtest", "2016-2022", "Antérieures au test"],\n        ["Principe", "Entraînement sur années strictement antérieures", "OK"],\n        ["Critère de règle hybride", "MAE agrégée historique par groupe", "Défini"],\n        ["Années test", "2023-2025", "Non utilisées pour établir la règle"],\n        ["Statut du résultat hybride", "Analyse de sensibilité post-hoc",\n         "À confirmer sur de nouvelles années"],\n    ], columns=["controle", "valeur", "statut"])\n\n    prediction_columns = [\n        "societe", "secteur_normalise", "groupe", "annee", "annee_cible",\n        "is_mad", TARGET, "prediction_naive", "prediction_delta",\n        "methode_hybride", "prediction_hybride",\n    ]\n    test[prediction_columns].to_csv(\n        PREDICTIONS, index=False, encoding="utf-8-sig"\n    )\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        rule.to_excel(writer, sheet_name="Regle historique", index=False)\n        historical.to_excel(writer, sheet_name="Backtest agrege", index=False)\n        metrics_by_fold.to_excel(writer, sheet_name="Backtest par annee", index=False)\n        comparison.to_excel(writer, sheet_name="Comparaison test", index=False)\n        test_groups.to_excel(writer, sheet_name="Test par groupe", index=False)\n        controls.to_excel(writer, sheet_name="Controles", index=False)\n\n    print("Règle déterminée uniquement sur 2016-2022 :")\n    print(rule.to_string(index=False))\n    print("\\nComparaison de sensibilité sur 2023-2025 :")\n    print(comparison.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT}")\n    print(f"Créé : {PREDICTIONS}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '39_modeles_econometriques_panel.py': '"""\nComparaison économétrique pour le panel des sociétés cotées.\n\nDeux objectifs sont séparés :\n1. l\'inférence, avec modèles pooled OLS, effets fixes et effets aléatoires,\n   estimés sur les années antérieures au test et erreurs standards robustes ;\n2. la prévision, évaluée sur 2023-2025 avec le même protocole temporel que le ML.\n\nLe modèle enrichi par le RCAI est évalué sur son propre sous-échantillon complet\nafin de ne pas comparer des erreurs calculées sur des observations différentes.\nLes montants sont divisés par un million lors de l\'estimation pour améliorer la\nstabilité numérique ; les métriques finales restent exprimées en MAD.\n"""\n\nfrom pathlib import Path\nimport warnings\n\nimport numpy as np\nimport pandas as pd\nfrom linearmodels.panel import PanelOLS, PooledOLS, RandomEffects\nfrom scipy.stats import chi2\nfrom sklearn.compose import ColumnTransformer\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.metrics import (\n    mean_absolute_error,\n    mean_squared_error,\n    median_absolute_error,\n    r2_score,\n)\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder\n\n\nOUT = Path("data/output")\nINPUT = OUT / "prevision_is_t_plus_1.csv"\nOUTPUT = OUT / "resultats_modeles_econometriques_panel.xlsx"\nPREDICTIONS = OUT / "predictions_test_modeles_panel.csv"\nTARGET = "is_cible_t_plus_1"\nSCALE = 1_000_000\n\n\ndef metrics(y_true, y_pred):\n    """Calcule les mêmes métriques que dans la comparaison Machine Learning."""\n    truth = np.asarray(y_true, dtype=float)\n    prediction = np.maximum(np.asarray(y_pred, dtype=float), 0)\n    return {\n        "MAE_MAD": mean_absolute_error(truth, prediction),\n        "RMSE_MAD": np.sqrt(mean_squared_error(truth, prediction)),\n        "MedAE_MAD": median_absolute_error(truth, prediction),\n        "R2": r2_score(truth, prediction),\n        "WAPE_pct": 100 * np.abs(truth - prediction).sum() / np.abs(truth).sum(),\n    }\n\n\ndef prepare_inference_data(data):\n    """Construit un index entreprise-année et met les montants en millions."""\n    sample = data[\n        data["annee_cible"].le(2022)\n    ].dropna(subset=[TARGET, "is_mad", "resultat_avant_impot"]).copy()\n    # Une entreprise peut apparaître sous deux périmètres comptables. La clé\n    # économétrique les distingue afin de préserver la cohérence longitudinale.\n    sample["entite"] = (\n        sample["societe"].astype(str)\n        + " | "\n        + sample["type_comptes_resolu"].astype(str)\n    )\n    sample["IS_futur_M"] = sample[TARGET] / SCALE\n    sample["IS_courant_M"] = sample["is_mad"] / SCALE\n    sample["RCAI_M"] = sample["resultat_avant_impot"] / SCALE\n    sample = sample.set_index(["entite", "annee_cible"]).sort_index()\n    return sample\n\n\ndef inference_models(data):\n    """Estime les modèles académiques et retourne coefficients et diagnostics."""\n    panel = prepare_inference_data(data)\n    y = panel["IS_futur_M"]\n    x = panel[["IS_courant_M", "RCAI_M"]].copy()\n    x["constante"] = 1.0\n\n    # Pooled OLS suppose une constante commune à toutes les sociétés.\n    pooled = PooledOLS(y, x).fit(cov_type="clustered", cluster_entity=True)\n\n    # Les effets fixes contrôlent les caractéristiques permanentes de chaque\n    # entreprise et les chocs communs à une année donnée.\n    fixed = PanelOLS(\n        y,\n        x[["IS_courant_M", "RCAI_M"]],\n        entity_effects=True,\n        time_effects=True,\n        drop_absorbed=True,\n        check_rank=False,\n    ).fit(cov_type="clustered", cluster_entity=True)\n\n    # Les effets aléatoires supposent que l\'effet individuel n\'est pas corrélé\n    # aux variables explicatives. Cette hypothèse sera comparée aux effets fixes.\n    random = RandomEffects(y, x).fit(cov_type="clustered", cluster_entity=True)\n\n    coefficient_rows = []\n    for name, result in [\n        ("Pooled OLS", pooled),\n        ("Effets fixes entreprise+année", fixed),\n        ("Effets aléatoires", random),\n    ]:\n        for variable in result.params.index:\n            coefficient_rows.append({\n                "modele": name,\n                "variable": variable,\n                "coefficient": result.params[variable],\n                "erreur_standard_robuste": result.std_errors[variable],\n                "statistique_t": result.tstats[variable],\n                "p_value": result.pvalues[variable],\n                "significatif_5pct": result.pvalues[variable] < 0.05,\n            })\n    coefficients = pd.DataFrame(coefficient_rows)\n\n    fit_stats = pd.DataFrame([\n        {\n            "modele": "Pooled OLS",\n            "observations": pooled.nobs,\n            "R2": pooled.rsquared,\n            "R2_within": getattr(pooled, "rsquared_within", np.nan),\n        },\n        {\n            "modele": "Effets fixes entreprise+année",\n            "observations": fixed.nobs,\n            "R2": fixed.rsquared,\n            "R2_within": fixed.rsquared_within,\n        },\n        {\n            "modele": "Effets aléatoires",\n            "observations": random.nobs,\n            "R2": random.rsquared,\n            "R2_within": random.rsquared_within,\n        },\n    ])\n\n    # Test de Hausman sur les coefficients communs. Une p-value faible favorise\n    # les effets fixes, car elle remet en cause l\'hypothèse des effets aléatoires.\n    common = fixed.params.index.intersection(random.params.index)\n    difference = fixed.params[common] - random.params[common]\n    covariance_difference = (\n        fixed.cov.loc[common, common] - random.cov.loc[common, common]\n    )\n    try:\n        statistic = float(\n            difference.T @ np.linalg.pinv(covariance_difference) @ difference\n        )\n        statistic = max(statistic, 0)\n        p_value = float(chi2.sf(statistic, len(common)))\n    except Exception:\n        statistic, p_value = np.nan, np.nan\n    hausman = pd.DataFrame([{\n        "test": "Hausman effets fixes vs aléatoires",\n        "statistique": statistic,\n        "degres_liberte": len(common),\n        "p_value": p_value,\n        "interpretation": (\n            "Effets fixes préférés" if pd.notna(p_value) and p_value < 0.05\n            else "Rejet des effets aléatoires non démontré"\n        ),\n    }])\n    return coefficients, fit_stats, hausman, panel.reset_index()\n\n\ndef predictive_pipeline(numeric, company_effect):\n    """Crée une régression prédictive avec ou sans effets propres aux sociétés."""\n    if company_effect:\n        preparation = ColumnTransformer([\n            ("numerique", "passthrough", numeric),\n            (\n                "entreprise",\n                OneHotEncoder(handle_unknown="ignore", drop="first"),\n                ["societe"],\n            ),\n        ])\n    else:\n        preparation = ColumnTransformer([("numerique", "passthrough", numeric)])\n    return Pipeline([\n        ("preparation", preparation),\n        ("regression", LinearRegression()),\n    ])\n\n\ndef predictive_comparison(data):\n    """Compare les modèles de panel sur le test final, à échantillon constant."""\n    train = data[data["annee_cible"].le(2022)].copy()\n    test = data[data["annee_cible"].ge(2023)].copy()\n    result_rows = []\n    prediction_table = test[\n        ["societe", "annee_cible", "secteur_normalise", "is_mad", TARGET]\n    ].copy()\n\n    scenarios = [\n        ("Panel complet", ["is_mad", "annee"], False),\n        ("Panel complet", ["is_mad", "annee"], True),\n        (\n            "Sous-echantillon RCAI",\n            ["is_mad", "resultat_avant_impot", "annee"],\n            False,\n        ),\n        (\n            "Sous-echantillon RCAI",\n            ["is_mad", "resultat_avant_impot", "annee"],\n            True,\n        ),\n    ]\n    for sample_name, numeric, company_effect in scenarios:\n        required = numeric + [TARGET]\n        train_sample = train.dropna(subset=required).copy()\n        test_sample = test.dropna(subset=required).copy()\n        model_name = (\n            "OLS avec effets entreprise" if company_effect else "Pooled OLS"\n        )\n        model = predictive_pipeline(numeric, company_effect)\n        model.fit(train_sample[numeric + ["societe"]], train_sample[TARGET])\n        prediction = np.maximum(\n            model.predict(test_sample[numeric + ["societe"]]), 0\n        )\n        result_rows.append({\n            "echantillon": sample_name,\n            "modele": model_name,\n            "observations_train": len(train_sample),\n            "observations_test": len(test_sample),\n            **metrics(test_sample[TARGET], prediction),\n        })\n\n        # La référence naïve est recalculée sur exactement le même sous-échantillon.\n        if not company_effect:\n            result_rows.append({\n                "echantillon": sample_name,\n                "modele": "Naif IS(t)",\n                "observations_train": len(train_sample),\n                "observations_test": len(test_sample),\n                **metrics(test_sample[TARGET], test_sample["is_mad"]),\n            })\n        column = (\n            f"prediction_{sample_name}_{model_name}"\n            .replace(" ", "_")\n            .replace("-", "_")\n        )\n        prediction_table.loc[test_sample.index, column] = prediction\n    return pd.DataFrame(result_rows), prediction_table\n\n\ndef main():\n    """Exécute l\'inférence, la prévision et les contrôles méthodologiques."""\n    data = pd.read_csv(INPUT).dropna(subset=[TARGET, "is_mad"]).copy()\n    coefficients, fit_stats, hausman, inference_sample = inference_models(data)\n    predictive_results, predictions = predictive_comparison(data)\n\n    coverage = pd.DataFrame([\n        {\n            "echantillon": "Panel complet",\n            "observations": len(data),\n            "entreprises": data["societe"].nunique(),\n            "variables": "IS(t), année",\n        },\n        {\n            "echantillon": "Sous-échantillon RCAI",\n            "observations": len(\n                data.dropna(subset=["resultat_avant_impot"])\n            ),\n            "entreprises": data.dropna(\n                subset=["resultat_avant_impot"]\n            )["societe"].nunique(),\n            "variables": "IS(t), RCAI(t), année",\n        },\n    ])\n    controls = pd.DataFrame([\n        ["Découpage prédictif", "Apprentissage <=2022; test 2023-2025", "OK"],\n        ["Erreurs standards", "Groupées par entreprise", "Robustes"],\n        ["Comparaison RCAI", "Même sous-échantillon pour tous les modèles", "OK"],\n        ["Montants estimation", "Millions de MAD", "Stabilité numérique"],\n        ["Montants métriques", "MAD", "Comparables au ML"],\n        ["Interprétation", "Association conditionnelle, non causalité", "Important"],\n    ], columns=["controle", "valeur", "statut"])\n\n    predictions.to_csv(PREDICTIONS, index=False, encoding="utf-8-sig")\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        predictive_results.to_excel(\n            writer, sheet_name="Performance predictive", index=False\n        )\n        coefficients.to_excel(writer, sheet_name="Coefficients", index=False)\n        fit_stats.to_excel(writer, sheet_name="Ajustement panel", index=False)\n        hausman.to_excel(writer, sheet_name="Test Hausman", index=False)\n        coverage.to_excel(writer, sheet_name="Couverture", index=False)\n        controls.to_excel(writer, sheet_name="Controles", index=False)\n        inference_sample.to_excel(\n            writer, sheet_name="Echantillon inference", index=False\n        )\n\n    print("Performances prédictives sur 2023-2025 :")\n    print(predictive_results.sort_values(\n        ["echantillon", "MAE_MAD"]\n    ).to_string(index=False))\n    print("\\nCoefficients économétriques :")\n    print(coefficients.to_string(index=False))\n    print("\\nTest de Hausman :")\n    print(hausman.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT}")\n    print(f"Créé : {PREDICTIONS}")\n\n\nif __name__ == "__main__":\n    warnings.filterwarnings("ignore")\n    main()\n',
    '40_corriger_rcai_anormaux.py': '"""\nCréation de la base financière V16 après audit des RCAI anormaux.\n\nLa V15 reste intacte. Chaque correction repose sur une preuve explicite dans le\nPDF : unité de page, séparation de colonnes annuelles ou cohérence avec la ligne\nfiscale publiée. Une feuille d\'audit conserve l\'ancienne valeur, la nouvelle\nvaleur, le motif et la source.\n"""\n\nfrom pathlib import Path\n\nimport pandas as pd\n\n\nOUT = Path("data/output")\nSOURCE = OUT / "variables_financieres_base_prevalidee_v15.xlsx"\nTARGET = OUT / "variables_financieres_base_prevalidee_v16.xlsx"\n\n# Clé : société, année, périmètre comptable.\n# Les valeurs finales sont toutes exprimées en MAD.\nCORRECTIONS = {\n    ("Rebab Company", 2022, "sociaux"): (\n        -219_000,\n        "Valeur (219) publiée en milliers de DH; IS publié 3 milliers de DH.",\n    ),\n    ("Rebab Company", 2023, "sociaux"): (\n        221_000,\n        "Valeur 221 publiée en milliers de DH; IS publié 3 milliers de DH.",\n    ),\n    ("Rebab Company", 2025, "sociaux"): (\n        1_031_000,\n        "Valeur 1 031 publiée en milliers de DH; IS publié 3 milliers de DH.",\n    ),\n    ("Risma", 2024, "sociaux"): (\n        73_046_000,\n        "Valeur sociale 73 046 en milliers de DH, et non en millions.",\n    ),\n    ("BMCE BANK", 2021, "sociaux"): (\n        2_010_343_000,\n        "Tableau en milliers de DH; trois années concaténées lors de l\'extraction.",\n    ),\n    ("DISTY RFA", 2021, "sociaux"): (\n        26_463_000,\n        "Valeur 26 463 en milliers de DH; cohérente avec RN de 18 MMAD.",\n    ),\n    ("DISTY RFA", 2022, "sociaux"): (\n        7_332_000,\n        "Valeur 7 332 en milliers de DH; impôt publié de 2 928 milliers.",\n    ),\n    ("Auto Nejma", 2024, "sociaux"): (\n        323_000_000,\n        "Tableau en MMAD : colonne 2024 = 323; 250 appartient à 2023.",\n    ),\n    ("Auto Nejma", 2025, "sociaux"): (\n        486_000_000,\n        "Tableau en MMAD : colonne 2025 = 486; 323 appartient à 2024.",\n    ),\n    ("Eqdom", 2007, "sociaux"): (\n        337_261_000,\n        "Tableau en milliers de DH : 337 261 pour 2007; 290 008 pour 2006.",\n    ),\n    ("Zellidja", 2025, "consolides"): (\n        33_990_000,\n        "Valeur 33 990 en milliers de DH; impôt publié de 6 170 milliers.",\n    ),\n}\n\n\ndef main():\n    """Copie le classeur, applique les corrections et ajoute la piste d\'audit."""\n    workbook = {\n        sheet: pd.read_excel(SOURCE, sheet_name=sheet)\n        for sheet in pd.ExcelFile(SOURCE).sheet_names\n    }\n    wide_sheet = pd.ExcelFile(SOURCE).sheet_names[0]\n    values_sheet = pd.ExcelFile(SOURCE).sheet_names[1]\n    wide = workbook[wide_sheet].copy()\n    values = workbook[values_sheet].copy()\n    # Les colonnes entièrement vides sont parfois lues comme numériques par\n    # pandas. Elles sont converties en objet avant d\'y inscrire du texte.\n    for column in ["commentaire_controle", "methode_validation"]:\n        values[column] = values[column].astype("object")\n    audit_rows = []\n\n    for (company, year, scope), (new_value, reason) in CORRECTIONS.items():\n        wide_mask = (\n            wide["societe"].eq(company)\n            & wide["annee"].eq(year)\n            & wide["type_comptes_resolu"].eq(scope)\n        )\n        if wide_mask.sum() != 1:\n            raise ValueError(\n                f"Clé absente ou non unique : {company}, {year}, {scope}"\n            )\n        old_value = wide.loc[wide_mask, "resultat_avant_impot"].iloc[0]\n        wide.loc[wide_mask, "resultat_avant_impot"] = new_value\n\n        value_mask = (\n            values["societe"].eq(company)\n            & values["annee"].eq(year)\n            & values["type_comptes_resolu"].eq(scope)\n            & values["variable"].eq("resultat_avant_impot")\n            & values["valeur_mad"].eq(old_value)\n        )\n        source_pdf = ""\n        page_pdf = pd.NA\n        raw_value = ""\n        if value_mask.any():\n            index = values.index[value_mask][0]\n            source_pdf = values.at[index, "source_pdf"]\n            page_pdf = values.at[index, "page_pdf"]\n            raw_value = values.at[index, "valeur_brute"]\n            values.at[index, "valeur_corrigee_mad"] = new_value\n            values.at[index, "commentaire_controle"] = reason\n            values.at[index, "methode_validation"] = "audit_rcai_pdf_v16"\n\n        audit_rows.append({\n            "societe": company,\n            "annee": year,\n            "type_comptes_resolu": scope,\n            "ancienne_valeur_mad": old_value,\n            "nouvelle_valeur_mad": new_value,\n            "facteur_correction": new_value / old_value if old_value else pd.NA,\n            "valeur_brute_pdf": raw_value,\n            "motif_correction": reason,\n            "source_pdf": source_pdf,\n            "page_pdf": page_pdf,\n            "statut": "corrige_preuve_pdf",\n        })\n\n    workbook[wide_sheet] = wide\n    workbook[values_sheet] = values\n    workbook["Audit corrections RCAI V16"] = pd.DataFrame(audit_rows)\n\n    with pd.ExcelWriter(TARGET, engine="openpyxl") as writer:\n        for sheet, frame in workbook.items():\n            # Excel limite les noms de feuilles à 31 caractères.\n            frame.to_excel(writer, sheet_name=sheet[:31], index=False)\n\n    audit = pd.DataFrame(audit_rows)\n    print("Corrections appliquées :", len(audit))\n    print(audit[[\n        "societe", "annee", "type_comptes_resolu",\n        "ancienne_valeur_mad", "nouvelle_valeur_mad",\n    ]].to_string(index=False))\n    print(f"\\nCréé : {TARGET}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '41_prevoir_is_2026.py': '"""\nPrévision opérationnelle de l\'IS 2026 à partir des informations de 2025.\n\nLe Gradient Boosting prédit la variation entre l\'IS 2025 et l\'IS 2026. Son\nréglage a été déterminé lors des étapes de validation précédentes, puis le\nmodèle est réentraîné ici sur toutes les paires historiques disponibles jusqu\'à\nla cible 2025.\n\nLes intervalles sont empiriques : ils utilisent les erreurs hors échantillon\nobservées en 2020-2025, séparément pour banques et non-banques. Ils représentent\nune incertitude historique, et non une garantie fiscale ou comptable.\n"""\n\nfrom importlib.util import module_from_spec, spec_from_file_location\nfrom pathlib import Path\n\nimport joblib\nimport numpy as np\nimport pandas as pd\n\n\nOUT = Path("data/output")\nPANEL_FILE = OUT / "diagnostic_panel_is_financier.xlsx"\nTRAIN_FILE = OUT / "prevision_is_t_plus_1.csv"\nOUTPUT_XLSX = OUT / "previsions_is_2026.xlsx"\nOUTPUT_CSV = OUT / "previsions_is_2026.csv"\nOUTPUT_MODEL = OUT / "modeles_is" / "modele_operationnel_is_2026.joblib"\nTARGET = "is_cible_t_plus_1"\nDELTA = "delta_is_cible"\n\n# Chargement des fonctions documentées sans recopier les traitements.\ndelta_spec = spec_from_file_location(\n    "delta_module", Path("37_analyse_erreurs_et_delta_is.py")\n)\ndelta_module = module_from_spec(delta_spec)\ndelta_spec.loader.exec_module(delta_module)\n\nfeature_spec = spec_from_file_location(\n    "feature_module", Path("34_prepare_modeling_datasets.py")\n)\nfeature_module = module_from_spec(feature_spec)\nfeature_spec.loader.exec_module(feature_module)\n\nPARAMS = {\n    "n_estimators": 100,\n    "learning_rate": 0.03,\n    "max_depth": 1,\n    "min_samples_leaf": 10,\n}\n\n\ndef build_model(numeric, categorical):\n    """Reconstruit le modèle delta avec le réglage sélectionné précédemment."""\n    return delta_module.make_model(\n        "GradientBoosting_delta", numeric, categorical, PARAMS\n    )\n\n\ndef out_of_sample_errors(data, features, numeric, categorical):\n    """Calibre l\'incertitude avec deux périodes réellement hors apprentissage."""\n    predictions = []\n    # Validation 2020-2022 : apprentissage limité à 2019.\n    # Test 2023-2025 : apprentissage limité à 2022.\n    for last_train_year, start_prediction, end_prediction in [\n        (2019, 2020, 2022),\n        (2022, 2023, 2025),\n    ]:\n        train = data[data["annee_cible"].le(last_train_year)]\n        evaluation = data[\n            data["annee_cible"].between(start_prediction, end_prediction)\n        ].copy()\n        model = build_model(numeric, categorical)\n        model.fit(train[features], train[DELTA])\n        predicted_delta = model.predict(evaluation[features])\n        evaluation["prediction"] = np.maximum(\n            evaluation["is_mad"] + predicted_delta, 0\n        )\n        evaluation["erreur_absolue"] = (\n            evaluation[TARGET] - evaluation["prediction"]\n        ).abs()\n        evaluation["groupe"] = np.where(\n            evaluation["est_banque"].str.lower().eq("true"),\n            "Banques",\n            "Non-banques",\n        )\n        predictions.append(evaluation)\n    return pd.concat(predictions, ignore_index=True)\n\n\ndef main():\n    """Entraîne sur tout l\'historique et exporte les prévisions de 2026."""\n    training = pd.read_csv(TRAIN_FILE).dropna(subset=[TARGET, "is_mad"]).copy()\n    training["est_banque"] = training["est_banque"].astype(str)\n    training[DELTA] = training[TARGET] - training["is_mad"]\n\n    numeric = [x for x in delta_module.NUMERIC if x in training.columns]\n    categorical = [\n        x for x in delta_module.CATEGORICAL if x in training.columns\n    ]\n    features = numeric + categorical\n\n    # Les variables 2025 sont reconstruites avec exactement les mêmes fonctions\n    # que celles utilisées lors de l\'entraînement.\n    panel = pd.read_excel(PANEL_FILE, sheet_name="Panel provisoire")\n    panel = panel.drop_duplicates(\n        ["societe", "annee", "type_comptes_resolu"], keep="first"\n    )\n    panel = feature_module.add_features(panel)\n    future = panel[\n        panel["annee"].eq(2025) & panel["is_mad"].notna()\n    ].copy()\n    future["est_banque"] = future["est_banque"].astype(str)\n\n    # Calibration des intervalles avant le réentraînement opérationnel.\n    calibration_predictions = out_of_sample_errors(\n        training, features, numeric, categorical\n    )\n    calibration = (\n        calibration_predictions.groupby("groupe")["erreur_absolue"]\n        .agg(\n            observations="count",\n            MAE="mean",\n            quantile_80=lambda x: x.quantile(0.80),\n            quantile_90=lambda x: x.quantile(0.90),\n            quantile_95=lambda x: x.quantile(0.95),\n        )\n        .reset_index()\n    )\n    q90 = calibration.set_index("groupe")["quantile_90"].to_dict()\n\n    # Le modèle final bénéficie de toutes les cibles connues jusqu\'en 2025.\n    model = build_model(numeric, categorical)\n    model.fit(training[features], training[DELTA])\n    predicted_delta = model.predict(future[features])\n    predicted_is = np.maximum(future["is_mad"].to_numpy() + predicted_delta, 0)\n\n    forecast = future[\n        [\n            "societe", "secteur", "secteur_normalise",\n            "type_comptes_resolu", "statut_perimetre_is", "qualite_perimetre",\n            "annee", "is_mad", "resultat_avant_impot", "resultat_net",\n            "chiffre_affaires", "total_actif", "capitaux_propres",\n            "est_banque", "version_source",\n        ]\n    ].copy()\n    forecast.rename(\n        columns={"annee": "annee_information", "is_mad": "is_2025_mad"},\n        inplace=True,\n    )\n    forecast["annee_prevue"] = 2026\n    forecast["prediction_naive_2026_mad"] = forecast["is_2025_mad"]\n    forecast["variation_is_predite_mad"] = predicted_delta\n    forecast["prediction_modele_2026_mad"] = predicted_is\n    forecast["groupe_intervalle"] = np.where(\n        forecast["est_banque"].str.lower().eq("true"),\n        "Banques",\n        "Non-banques",\n    )\n    forecast["marge_empirique_90_mad"] = (\n        forecast["groupe_intervalle"].map(q90)\n    )\n    forecast["borne_basse_90_mad"] = np.maximum(\n        forecast["prediction_modele_2026_mad"]\n        - forecast["marge_empirique_90_mad"],\n        0,\n    )\n    forecast["borne_haute_90_mad"] = (\n        forecast["prediction_modele_2026_mad"]\n        + forecast["marge_empirique_90_mad"]\n    )\n    forecast["statut_prevision"] = (\n        "Prévision exploratoire; à actualiser avec les comptes 2026"\n    )\n    forecast.sort_values(\n        "prediction_modele_2026_mad", ascending=False, inplace=True\n    )\n\n    methodology = pd.DataFrame([\n        ["Année prévue", 2026],\n        ["Informations utilisées", "Données annuelles disponibles en 2025"],\n        ["Modèle", "Gradient Boosting sur variation IS(t+1)-IS(t)"],\n        ["Référence", "IS 2026 = IS 2025"],\n        ["Entraînement final", f"{len(training)} paires historiques jusqu\'à 2025"],\n        ["Intervalle", "Quantile 90 % des erreurs hors échantillon 2020-2025"],\n        ["Limite", "Prévision conditionnelle aux données 2025; non garantie"],\n        ["Prévision 2027", "Non produite sans variables financières 2026"],\n    ], columns=["element", "description"])\n\n    controls = pd.DataFrame([\n        ["Entreprises prévues", len(forecast), "Information"],\n        ["Cibles 2026 utilisées à l\'entraînement", 0, "OK"],\n        ["Données d\'information", 2025, "OK"],\n        ["Valeurs prédites négatives après plancher", int((predicted_is < 0).sum()), "OK"],\n        ["Version financière", feature_module.SOURCE_VERSION, "Vérifiée"],\n    ], columns=["controle", "valeur", "statut"])\n\n    OUTPUT_MODEL.parent.mkdir(parents=True, exist_ok=True)\n    joblib.dump(\n        {\n            "modele": model,\n            "variables": features,\n            "cible": DELTA,\n            "annee_prevue": 2026,\n            "calibration_intervalles": calibration,\n        },\n        OUTPUT_MODEL,\n    )\n    forecast.to_csv(OUTPUT_CSV, index=False, encoding="utf-8-sig")\n    with pd.ExcelWriter(OUTPUT_XLSX, engine="openpyxl") as writer:\n        forecast.to_excel(writer, sheet_name="Previsions IS 2026", index=False)\n        calibration.to_excel(writer, sheet_name="Calibration intervalles", index=False)\n        calibration_predictions[\n            [\n                "societe", "annee_cible", "est_banque", TARGET,\n                "prediction", "erreur_absolue",\n            ]\n        ].to_excel(writer, sheet_name="Erreurs calibration", index=False)\n        methodology.to_excel(writer, sheet_name="Methodologie", index=False)\n        controls.to_excel(writer, sheet_name="Controles", index=False)\n\n    print("Prévisions IS 2026 :", len(forecast), "entreprises")\n    print("\\nCalibration des intervalles :")\n    print(calibration.to_string(index=False))\n    print("\\nAperçu des prévisions les plus élevées :")\n    print(forecast[[\n        "societe", "is_2025_mad", "variation_is_predite_mad",\n        "prediction_modele_2026_mad", "borne_basse_90_mad",\n        "borne_haute_90_mad",\n    ]].head(10).to_string(index=False))\n    print(f"\\nCréé : {OUTPUT_XLSX}")\n    print(f"Créé : {OUTPUT_CSV}")\n    print(f"Créé : {OUTPUT_MODEL}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '42_audit_cible_is_et_variations.py': '"""\nRegistre d\'audit de la cible IS et de ses variations annuelles extrêmes.\n\nLe script ne corrige ni ne supprime aucune observation. Il rassemble les cas à\nexaminer, applique des règles transparentes et indique le niveau de priorité.\nUne correction future exigera une preuve fiscale ou documentaire explicite.\n"""\n\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\n\nOUT = Path("data/output")\nINPUT = OUT / "prevision_is_t_plus_1.csv"\nOUTPUT = OUT / "audit_cible_is_et_variations.xlsx"\n\n\ndef main():\n    data = pd.read_csv(INPUT).copy()\n    data["delta_is_mad"] = data["is_cible_t_plus_1"] - data["is_mad"]\n    data["ratio_is_futur_courant"] = (\n        data["is_cible_t_plus_1"] / data["is_mad"].abs().clip(lower=1)\n    )\n    data["is_courant_tres_faible"] = data["is_mad"].le(100_000)\n    data["is_futur_tres_faible"] = data["is_cible_t_plus_1"].le(100_000)\n    data["variation_relative_extreme"] = (\n        data["ratio_is_futur_courant"].gt(3)\n        | data["ratio_is_futur_courant"].lt(1 / 3)\n    )\n    data["variation_absolue_extreme"] = data["delta_is_mad"].abs().gt(100_000_000)\n    data["perimetre_provisoire"] = data["qualite_perimetre"].ne("haute")\n\n    # La priorité forte combine plusieurs alertes ou une cible faible avec un\n    # périmètre encore provisoire.\n    alert_columns = [\n        "is_courant_tres_faible", "is_futur_tres_faible",\n        "variation_relative_extreme", "variation_absolue_extreme",\n        "perimetre_provisoire",\n    ]\n    data["nombre_alertes"] = data[alert_columns].sum(axis=1)\n    data["priorite_audit"] = np.select(\n        [\n            data["nombre_alertes"].ge(3),\n            data["nombre_alertes"].eq(2),\n            data["nombre_alertes"].eq(1),\n        ],\n        ["forte", "moyenne", "faible"],\n        default="aucune",\n    )\n    data["decision_actuelle"] = np.where(\n        data["priorite_audit"].eq("aucune"),\n        "Conserver",\n        "Conserver et contrôler; aucune correction sans preuve",\n    )\n\n    flagged = data[data["priorite_audit"].ne("aucune")].copy()\n    low_is = data[\n        data["is_courant_tres_faible"] | data["is_futur_tres_faible"]\n    ].copy()\n    extreme_relative = data[data["variation_relative_extreme"]].copy()\n    extreme_absolute = data[data["variation_absolue_extreme"]].copy()\n    summary = pd.DataFrame([\n        ["Observations totales", len(data)],\n        ["IS courant <= 100 000 MAD", int(data["is_courant_tres_faible"].sum())],\n        ["IS futur <= 100 000 MAD", int(data["is_futur_tres_faible"].sum())],\n        ["Variation > x3 ou < /3", int(data["variation_relative_extreme"].sum())],\n        ["Variation absolue > 100 M MAD", int(data["variation_absolue_extreme"].sum())],\n        ["Priorité forte", int(data["priorite_audit"].eq("forte").sum())],\n        ["Priorité moyenne", int(data["priorite_audit"].eq("moyenne").sum())],\n    ], columns=["indicateur", "valeur"])\n    rules = pd.DataFrame([\n        ["IS faible", "IS <= 100 000 MAD", "Signalement, pas suppression"],\n        ["Variation relative", "IS(t+1)/IS(t) > 3 ou < 1/3", "Contrôle événement fiscal"],\n        ["Variation absolue", "|IS(t+1)-IS(t)| > 100 M MAD", "Contrôle grandes entreprises"],\n        ["Périmètre", "Qualité différente de haute", "Contrôle social/consolidé"],\n        ["Correction", "Preuve PDF ou base fiscale nécessaire", "Règle obligatoire"],\n    ], columns=["controle", "regle", "traitement"])\n\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        summary.to_excel(writer, sheet_name="Resume", index=False)\n        flagged.to_excel(writer, sheet_name="Registre audit", index=False)\n        low_is.to_excel(writer, sheet_name="IS faibles", index=False)\n        extreme_relative.to_excel(writer, sheet_name="Variations relatives", index=False)\n        extreme_absolute.to_excel(writer, sheet_name="Variations absolues", index=False)\n        rules.to_excel(writer, sheet_name="Regles audit", index=False)\n    print(summary.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT}")\n\n\nif __name__ == "__main__":\n    main()\n',
    '43_calibrer_correction_partielle.py': '"""\nCalibration d\'une correction partielle du modèle de variation de l\'IS.\n\nLa prévision est :\n    IS_prédit(t+1) = IS(t) + lambda * delta_IS_prédit\n\nlambda=0 correspond au naïf et lambda=1 au Gradient Boosting complet. Le lambda\nest choisi exclusivement sur des prédictions temporelles hors échantillon de\n2016 à 2022. Le test 2023-2025 ne sert pas à déterminer sa valeur.\n"""\n\nfrom importlib.util import module_from_spec, spec_from_file_location\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\n\nOUT = Path("data/output")\nINPUT = OUT / "prevision_is_t_plus_1.csv"\nOUTPUT = OUT / "calibration_correction_partielle_is.xlsx"\nPREDICTIONS = OUT / "predictions_test_correction_partielle.csv"\nTARGET = "is_cible_t_plus_1"\nDELTA = "delta_is_cible"\nLAMBDAS = np.round(np.arange(0, 1.01, 0.05), 2)\n\nspec = spec_from_file_location("delta_module", Path("37_analyse_erreurs_et_delta_is.py"))\ndelta_module = module_from_spec(spec)\nspec.loader.exec_module(delta_module)\n\nPARAMS = {\n    "n_estimators": 100,\n    "learning_rate": 0.03,\n    "max_depth": 1,\n    "min_samples_leaf": 10,\n}\n\n\ndef predict_folds(data, years, numeric, categorical, features):\n    """Produit une prévision delta strictement hors échantillon pour chaque année."""\n    rows = []\n    for year in years:\n        train = data[data["annee_cible"].lt(year)]\n        evaluation = data[data["annee_cible"].eq(year)].copy()\n        if len(train) < 50 or evaluation.empty:\n            continue\n        model = delta_module.make_model(\n            "GradientBoosting_delta", numeric, categorical, PARAMS\n        )\n        model.fit(train[features], train[DELTA])\n        evaluation["delta_predit"] = model.predict(evaluation[features])\n        rows.append(evaluation)\n    return pd.concat(rows, ignore_index=True)\n\n\ndef lambda_table(frame, period):\n    """Compare tous les poids sur le niveau final de l\'IS."""\n    rows = []\n    for value in LAMBDAS:\n        prediction = np.maximum(\n            frame["is_mad"] + value * frame["delta_predit"], 0\n        )\n        result = delta_module.score_level(frame[TARGET], prediction)\n        rows.append({"periode": period, "lambda": value, **result})\n    return pd.DataFrame(rows)\n\n\ndef main():\n    data = pd.read_csv(INPUT).dropna(subset=[TARGET, "is_mad"]).copy()\n    data["est_banque"] = data["est_banque"].astype(str)\n    data[DELTA] = data[TARGET] - data["is_mad"]\n    numeric = [x for x in delta_module.NUMERIC if x in data.columns]\n    categorical = [x for x in delta_module.CATEGORICAL if x in data.columns]\n    features = numeric + categorical\n\n    historical = predict_folds(\n        data, range(2016, 2023), numeric, categorical, features\n    )\n    calibration = lambda_table(historical, "Backtest 2016-2022")\n    selected = calibration.sort_values(["MAE_MAD", "lambda"]).iloc[0]\n    selected_lambda = float(selected["lambda"])\n\n    # Le modèle final est entraîné jusqu\'en 2022 seulement avant l\'évaluation du\n    # test 2023-2025.\n    train = data[data["annee_cible"].le(2022)]\n    test = data[data["annee_cible"].ge(2023)].copy()\n    model = delta_module.make_model(\n        "GradientBoosting_delta", numeric, categorical, PARAMS\n    )\n    model.fit(train[features], train[DELTA])\n    test["delta_predit"] = model.predict(test[features])\n    test["prediction_naive"] = test["is_mad"]\n    test["prediction_delta_complete"] = np.maximum(\n        test["is_mad"] + test["delta_predit"], 0\n    )\n    test["prediction_correction_partielle"] = np.maximum(\n        test["is_mad"] + selected_lambda * test["delta_predit"], 0\n    )\n\n    comparison_rows = []\n    for name, column in [\n        ("Naif lambda=0", "prediction_naive"),\n        (f"Correction partielle lambda={selected_lambda:g}",\n         "prediction_correction_partielle"),\n        ("Delta complet lambda=1", "prediction_delta_complete"),\n    ]:\n        comparison_rows.append({\n            "modele": name,\n            **delta_module.score_level(test[TARGET], test[column]),\n        })\n    comparison = pd.DataFrame(comparison_rows).sort_values("MAE_MAD")\n\n    controls = pd.DataFrame([\n        ["Période calibration lambda", "2016-2022", "Avant test"],\n        ["Critère", "MAE agrégée", "Défini avant test"],\n        ["Lambda sélectionné", selected_lambda, "Résultat historique"],\n        ["Période test", "2023-2025", "Non utilisée pour sélectionner lambda"],\n    ], columns=["controle", "valeur", "statut"])\n\n    test.to_csv(PREDICTIONS, index=False, encoding="utf-8-sig")\n    with pd.ExcelWriter(OUTPUT, engine="openpyxl") as writer:\n        calibration.to_excel(writer, sheet_name="Calibration lambda", index=False)\n        comparison.to_excel(writer, sheet_name="Comparaison test", index=False)\n        historical.to_excel(writer, sheet_name="Predictions backtest", index=False)\n        test.to_excel(writer, sheet_name="Predictions test", index=False)\n        controls.to_excel(writer, sheet_name="Controles", index=False)\n\n    print("Lambda sélectionné sur 2016-2022 :", selected_lambda)\n    print("\\nComparaison 2023-2025 :")\n    print(comparison.to_string(index=False))\n    print(f"\\nCréé : {OUTPUT}")\n    print(f"Créé : {PREDICTIONS}")\n\n\nif __name__ == "__main__":\n    main()\n',
}


def list_scripts() -> None:
    """Affiche les étapes historiques disponibles dans ce regroupement."""
    for script_name in sorted(SCRIPTS):
        print(script_name)


def run_script(script_name: str) -> None:
    """Exécute un script historique dans un espace de noms isolé."""
    normalized = script_name if script_name.endswith(".py") else f"{script_name}.py"
    if normalized not in SCRIPTS:
        choices = ", ".join(sorted(SCRIPTS))
        raise SystemExit(f"Script inconnu : {script_name}\nChoix disponibles : {choices}")

    previous_directory = Path.cwd()
    os.chdir(PROJECT_ROOT)
    namespace = {
        "__name__": "__main__",
        "__file__": str(PROJECT_ROOT / normalized),
        "__package__": None,
    }
    try:
        source = SCRIPTS[normalized]
        exec(compile(source, namespace["__file__"], "exec"), namespace)
    finally:
        os.chdir(previous_directory)


def main() -> None:
    """Afficher le catalogue interne ou lancer une analyse ou modélisation."""
    parser = argparse.ArgumentParser(
        description="Lister ou exécuter une étape historique regroupée."
    )
    parser.add_argument("script", nargs="?", help="Nom du script à exécuter.")
    parser.add_argument(
        "--list", action="store_true", help="Afficher les scripts disponibles."
    )
    args = parser.parse_args()

    if args.list or not args.script:
        list_scripts()
        return
    run_script(args.script)


if __name__ == "__main__":
    main()
